(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0032.js"] = [{"id":"poem-d143c79c4614f256cc457fb7","title":"晚渡伊水","author":"韦述","dynasty":"唐","verses":["悠悠涉伊水，伊水清见石。","是时春向深，两岸草如积。","迢遰望洲屿，逶迤亘津陌。","新树落疎红，遥原上深碧。","回瞻洛阳苑，遽有长山隔。","烟雾犹辨家，风尘已为客。","登陟多异趣，往来见行役。","云起早已昏，鸟飞日将夕。","光阴逝不借，超然慕畴昔。","远游亦何为？归来存竹帛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-13cbd4e0-e3f8-41a9-bf75-39f175bf6c34","tags":[]},{"id":"poem-d145a8bafcb59c1ca5dfa6bf","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净］才貌兼全，亲老家贫囊又艰，羞杀荆钗裙布，绣褥金屏，绮席华筵。","好姻缘番做恶姻缘，富亲眷强似穷亲眷。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8072","tags":[]},{"id":"poem-d147b204de9f29b598c62f0a","title":"渔歌子·草芊芊","author":"孙光宪","dynasty":"五代","verses":["草芊芊，波漾漾，湖边草色连波涨。","沿蓼岸，泊飘汀，天际玉轮初上。","扣舷歌，联极望，桨声伊轧知何向。","黄鹊叫，白鸥眠，谁似侬家疏旷。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-46","tags":[]},{"id":"poem-d14f40398cce0a3ee74bf8b4","title":"次韵君实内翰同游范景仁东园","author":"苏颂","dynasty":"宋","verses":["銮禁限沉深，鼇头雄赑屭。","主人出休沐，秋色正明丽。","偶为东园游，便有中林意。","纵言得造适，览物增意气。","风清濯烦襟，日永忘归辔。","朝野本无间，簪组何用弃。","未必幽栖人，识兹真乐地。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0f4f5287-7f0f-4de3-8443-034c06df7410","tags":[]},{"id":"poem-d155ef5f976be8cd39c62f30","title":"嘲小儿","author":"卢肇","dynasty":"唐","verses":["贪生只爱眼前珍，不觉风光度岁频。","昨日见来骑竹马，今朝早是有年人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-92369195-889f-414e-8045-88e4a9e3c3d9","tags":[]},{"id":"poem-d15ad3c6857458bc6b5074b7","title":"寄河上段十六","author":"卢象","dynasty":"唐","verses":["与君相识即相亲，闻道君家住孟津。","为见行舟试借问，客中时有洛阳人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a6306074-ffac-44d0-848d-eb72dfc04a9b","tags":[]},{"id":"poem-d161eac12a5003fa1267b848","title":"青玉案·绿琐窗纱明月透","author":"李祁","dynasty":"宋","verses":["绿琐窗纱明月透。","正清梦、莺啼柳。","碧井银瓶鸣玉甃。","翔鸾妆样，粲花衫绣。","分付春风手。","喜入秋波娇欲溜。","脉脉青山两眉秀。","玉枕春寒郎知否。","归来留取，御香襟袖。","同饮酴醿酒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-599","tags":[]},{"id":"poem-d16ff9476c2fe337c5602656","title":"独步至洛滨  其二","author":"司马光","dynasty":"宋","verses":["草软波清沙径微，手携筇竹著深衣。","白鸥不信忘机久，见我犹穿岸柳飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ba70340f-54f9-4421-b10c-260556bdaf63","tags":[]},{"id":"poem-d17dbe1dc83da40d320f0fc3","title":"句","author":"李揆","dynasty":"唐","verses":["免相践蓬阁，卧疴淮海滨。","偶逢潘川守，宛是洛阳亲。","（「洛阳」，《四部丛刊》影明本、中华上编本《唐诗纪事》皆作「潘阳」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-db2932d1-8a3f-4693-b68a-99f4dae77969","tags":[]},{"id":"poem-d183e4ba9026d36324001840","title":"木兰花减字・减字木兰花·匀红点翠","author":"陈师道","dynasty":"宋","verses":["匀红点翠。","取次梳妆谁得似。","风柳腰肢。","尽日纤柔属阿谁。","娇娇小小。","却是寻春人较老。","著便休痴。","付与风流幕下儿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-319","tags":[]},{"id":"poem-d184f857ea79001814f113c0","title":"上东林和尚","author":"贯休","dynasty":"唐","verses":["让紫归青壁，高名四海闻。","虽然无一事，得不是要君。","道祗传伊字，诗多笑碧云。","应怜门下客，余力亦为文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e6791481-45a7-4c10-a119-22c2963708f1","tags":[]},{"id":"poem-d1899f332bcfa3a32653c527","title":"郊庙歌辞 祀圜丘乐章 舒和","author":"褚亮","dynasty":"唐","verses":["叠璧凝影皇坛路，编珠流彩帝郊前。","已奏黄钟歌大吕，还符宝历祚昌年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6760691a-685c-4e01-9f8b-3e7384ed92fd","tags":[]},{"id":"poem-d1a0adc545e86c6183570276","title":"陪章留后惠义寺饯嘉州崔都督赴州","author":"杜甫","dynasty":"唐","verses":["中军待上客，令肃事有恒。","前驱入宝地，祖帐飘金绳。","南陌既留欢，兹山亦深登。","清闻树杪磬，远谒云端僧。","回策匪新岸，所攀仍旧藤。","耳激洞门飙，目存寒谷冰。","出尘閟轨躅，毕景遗炎蒸。","永愿坐长夏，将衰栖大乘。","羁旅惜宴会，艰难怀友朋。","劳生共几何，离恨兼相仍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5b62d8e7-b536-450c-978d-edbe5e7a4db3","tags":[]},{"id":"poem-d1a21a56d002d1d4e535ff4e","title":"高阳台","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["宦海沉身，京尘迷目，名缰利锁难脱。","目断家乡，空劳魂梦飞越。","闲聒，闲藤野蔓休缠也，俺自有正兔丝和那的亲瓜葛。","是谁人，无端调引，谩劳饶舌。","(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5007","tags":[]},{"id":"poem-d1a9210d61db9f55a0b25427","title":"定西番·紫塞月明千里","author":"牛峤","dynasty":"五代","verses":["紫塞月明千里，金甲冷，戍楼寒，梦长安。","乡思望中天阔，漏残星亦残。","画角数声呜咽，雪漫漫。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-22","tags":[]},{"id":"poem-d1b7a9780fd376c0cb9fd40b","title":"长庆和尚赞","author":"省澄","dynasty":"唐","verses":["缁黄深郑重，格峻实难当。","尽机相见处，立下闭僧堂。","（同前卷十。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-75fab832-bfce-448b-8fab-728ff2138c4a","tags":[]},{"id":"poem-d1b9b28169173fd05e729da6","title":"咏鞘","author":"张𬸦","dynasty":"唐","verses":["数捺皮应缓，频磨快转多。","渠今拔出后，空鞘欲如何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8f5efe34-843b-45db-8e70-7b035c2013b8","tags":[]},{"id":"poem-d1c750697c84bdf8704ea9a7","title":"兰陵王·柳阴直","author":"周邦彦","dynasty":"宋","verses":["柳阴直。","烟里丝丝弄碧。","隋堤上、曾见几番，拂水飘绵送行色。","登临望故国。","谁识。","京华倦客。","长亭路，年去岁来，应折柔条过千尺。","闲寻旧踪迹。","又酒趁哀弦，灯照离席。","梨花榆火催寒食。","愁一箭风快，半篙波暖，回头迢递便数驿。","望人在天北。","凄恻。","恨堆积。","渐别浦萦回，津堠岑寂。","斜阳冉冉春无极。","念月榭携手，露桥闻笛。","沈思前事，似梦里，泪暗滴。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-237","tags":["宋词三百首"]},{"id":"poem-d1cc75a6f9e38c7776ffcc1b","title":"洛阳春・一落萦·红纱未晓黄鹂语","author":"欧阳修","dynasty":"宋","verses":["红纱未晓黄鹂语。","蕙炉销兰炷。","锦屏罗幕护春寒，昨夜三更雨。","绣帘闲倚吹轻絮。","敛眉山无绪。","看花拭泪向归鸿，问来处、逢郎否。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-752","tags":[]},{"id":"poem-d1d6f6b188e73d96d00d1320","title":"送华阴隐者","author":"项斯","dynasty":"唐","verses":["往往到城市，得非征药钱。","世人空识面，弟子莫知年。","自说能医死，相期更学仙。","近来移住处，毛女旧峰前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-fc39b9dc-841f-4da9-8ba0-e6c398081166","tags":[]},{"id":"poem-d1d78ba8bc453ffbe8daa5b4","title":"玉阶怨","author":"李白","dynasty":"唐","verses":["玉阶生白露，夜久侵罗袜。","却下水晶帘，玲珑望秋月。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a65e5646-14b1-4f75-924b-bbf262b242d7","tags":["孤独","宫怨","唐诗三百首","乐府"]},{"id":"poem-d1dcc7daf67ea0f635c40e46","title":"渔家傲·塞下秋来风景异","author":"范仲淹","dynasty":"宋","verses":["塞下秋来风景异。","衡阳雁去无留意。","四面边声连角起。","千嶂里。","长烟落日孤城闭。","浊酒一杯家万里。","燕然未勒归无计。","羌管悠悠霜满地。","人不寐。","将军白发征夫泪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-42","tags":[]},{"id":"poem-d1eff22eb7c4aa6e20b02098","title":"女冠子","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["媳妇事舅姑合体例，怎不教女孩儿同去？当初是相公相留住，今日里怨着谁？(外)我不教女孩儿同去，又待怎地？(净)事须近理，怎挟威势？休道朝中太师威如火，更有路上行人口似碑。","(合)想起，此事费人区处。","(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5246","tags":[]},{"id":"poem-d1f08abfa2c53253c02c3e7c","title":"天南怀故人","author":"于邺","dynasty":"唐","verses":["独行千里尘，轧轧转征轮。","一别已多日，总看成老人。","洞庭雪不下，故国草应春。","三月烟波暖，南风生绿苹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7b666abe-efd8-453c-81f2-b0f5ddddd494","tags":["洞庭湖"]},{"id":"poem-d1fae646afb4048bafb3bcac","title":"冬夜与修睦上人宿远公亭寄南岳玄泰禅师","author":"李咸用","dynasty":"唐","verses":["丈室掩孤灯，更深霰雹增。","相看云梦客，共忆祝融僧。","语合茶忘味，吟欹卷有棱。","楚南山水秀，行止岂无凭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3158fdcf-4e90-438b-b999-37b423d08756","tags":["衡山"]},{"id":"poem-d204955e644b9fd0d7fae40b","title":"蚬子和尚赞","author":"释了惠","dynasty":"宋","verses":["得恁么自在，得恁么快活。","古庙当丛林，捞波作衣钵。","脚头到处江天阔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-0c9ab671-9900-4ad3-aa39-ebf916f6d2a9","tags":[]},{"id":"poem-d206ff3aa750ddfcf0f656c9","title":"句","author":"来鹄","dynasty":"唐","verses":["回眸绿水波初起，合掌白莲花未开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c6d55862-018e-4602-9f98-3ee3123133e4","tags":[]},{"id":"poem-d20aa795f0752f99c60ddfcc","title":"初晴落景","author":"太宗皇帝","dynasty":"唐","verses":["晚霞聊自怡，初晴弥可喜。","日晃百花色，风动千林翠。","池鱼跃不同，园鸟声还异。","寄言博通者，知予物外志。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-847b969b-de24-48b5-9917-29f1e0233c08","tags":[]},{"id":"poem-d20eb62c463ba5b1543793b5","title":"除歙州途中寄座主王侍郎","author":"卢肇","dynasty":"唐","verses":["忽忝专城奉六条，自怜出谷屡迁乔。","驱车虽道还家近，捧日惟愁去国遥。","朱户昨经新棨戟，风帆常觉恋箪瓢。","江天夜夜知消息，长见台星在碧霄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-827f90ed-ddc0-45ff-b874-6958be37aabe","tags":[]},{"id":"poem-d2126283c174f95f982975e3","title":"次韵惠寺丞见寄","author":"释居简","dynasty":"宋","verses":["雁塔名题久不知，新吟忽遣好风吹。","易推未画本无画，计已出奇何有奇。","孔雀屏开金错落，蟾蜍玉冷墨淋漓。","故家旧有传衣句，跨灶冲楼足尉思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-80d4c80f-a49b-4e84-8c66-376b0ee28c27","tags":[]},{"id":"poem-d2134334e0850e6d640054b8","title":"诉衷情·春深花簇小楼台","author":"魏承班","dynasty":"五代","verses":["春深花簇小楼台，风飘锦绣开。","新睡觉，步香阶，山枕印红腮。","鬓乱坠金钗，语檀偎。","临行执手重重嘱，几千回。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-5","tags":[]},{"id":"poem-d21f496af0c38bdca5f50e92","title":"墨梅  其一","author":"释居简","dynasty":"宋","verses":["描邈檀栾黪素元，万红千紫失根源。","大玄自古人嫌白，白尽何妨反太玄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1727b384-d7f0-4b2f-b40b-c0a9203d5462","tags":[]},{"id":"poem-d22c8d993f4e6fdf3f0a74a7","title":"生查子·关山魂梦长","author":"晏几道","dynasty":"宋","verses":["关山魂梦长，鱼雁音尘少。","两鬓可怜青，只为相思老。","归梦碧纱窗，说与人人道。","真个别离难，不似相逢好。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-24","tags":["宋词三百首"]},{"id":"poem-d235863e6f039bad711a78c3","title":"老融放耕图皇甫都护雁图二绝  其一","author":"释居简","dynasty":"宋","verses":["蓑笠从衡觳觫蕃，暝归晨作俟丰年。","诛求莫挠鸡豚社，春雨春寒苦最先。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-954f87b1-413f-4414-8a22-843651ab1ad0","tags":[]},{"id":"poem-d236bfa5e3c26a323b52a0e5","title":"古意四首  其二","author":"李纲","dynasty":"宋","verses":["薰莸不同器，枭鸾不接翼。","君看冰炭姿，燥湿更相息。","消长本天行，否泰非人力。","须知坦荡荡，自胜长戚戚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-9c0884ae-0b3c-4bad-b31f-f91ad96dd9ea","tags":[]},{"id":"poem-d23c79e2fbeec4623c7ea659","title":"与胡汾坐月期贯休上人不至","author":"曹松","dynasty":"唐","verses":["扫庭秋漏滴，接话贵忘眠。","静夜人相语，低枝鸟暗迁。","星围南极定，月照断河连。","后会花宫子，应开石上禅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-725fe5df-06bf-467d-9db2-1b37c9ec7130","tags":[]},{"id":"poem-d23c9886f64881023fd5d6b0","title":"送王六觐巢县叔父二首 一","author":"李涉","dynasty":"唐","verses":["巢岸南分战鸟山，水云程尽到东关。","弦歌自是君家事，莫怪今来一邑闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9de495a6-9a74-4dc7-b14e-8577611ba318","tags":[]},{"id":"poem-d24112c6df085cdd4d19abfd","title":"浣溪沙·寂寞流苏冷绣茵","author":"阎选","dynasty":"五代","verses":["寂寞流苏冷绣茵，倚屏山枕惹香尘，小庭花露泣浓香。","刘阮信非仙洞客，嫦娥终是月中人，此生无路访东邻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-23","tags":[]},{"id":"poem-d2444961dd39b62533be99ac","title":"眼儿媚·重见星娥碧海槎","author":"纳兰性德","dynasty":"清","verses":["重见星娥碧海槎，忍笑却盘鸦。","寻常多少，月明风细，今夜偏佳。","休笼彩笔闲书字，街鼓巳三挝。","烟丝欲袅，露光微泫，春在桃花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-36","tags":[]},{"id":"poem-d24ce0ba585b30d250ca64e8","title":"奉送杜侍御还京","author":"皇甫曾","dynasty":"唐","verses":["罢战回龙节，朝天上凤池。","寒生五湖道，春入万年枝。","召化多遗爱，胡清已畏知。","怀恩偏感别，堕泪向旌麾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-432d77a0-08de-44b9-a3c4-06db88347496","tags":[]},{"id":"poem-d24d1c68cfcca1e74085cfa4","title":"梦李白二首 一","author":"杜甫","dynasty":"唐","verses":["死别已吞声，生别常恻恻。","江南瘴疠地，逐客无消息。","故人入我梦，明我长相忆。","恐非平生魂，路远不可测。","魂来枫叶青，魂返关塞黑。","君今在罗网，何以有羽翼。","落月满屋梁，犹疑照颜色。","水深波浪阔，无使蛟龙得。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c9362aba-fb50-481b-a4cd-08ddd65cdd2a","tags":["唐诗三百首"]},{"id":"poem-d254e0775b1a74ed18388262","title":"减字木兰花·垂螺近额","author":"张先","dynasty":"宋","verses":["垂螺近额。","走上红裀初趁拍。","只恐轻飞。","拟倩游丝惹住伊。","文鸳绣履。","去似杨花尘不起。","舞彻伊州。","头上宫花颤未休。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-328","tags":[]},{"id":"poem-d255bb2e8f65105581a886cb","title":"送友人","author":"李白","dynasty":"唐","verses":["青山横北郭，白水遶东城。","此地一为别，孤蓬万里征。","浮云游子意，落日故人情。","挥手自兹去，萧萧班马鸣。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1f83fccf-7476-464b-8cd4-8a2b4569c7a0","tags":["唐诗三百首","八年级上册(课外)","友情","写景","送别","五言律诗","初中古诗","惜别"]},{"id":"poem-d262cd5a4d35fef13ce0acf5","title":"晚秋 三","author":"佚名","dynasty":"唐","verses":["缧绁戎庭恨有余，蚕知君意复何如？一介耻无苏子节，数回羞寄李陵书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-70a42a5f-4e1b-4845-9c73-114ad9d94734","tags":[]},{"id":"poem-d27a4d06a12a01e7d62de59b","title":"送赵法师还蜀因名山奠简","author":"明皇帝","dynasty":"唐","verses":["道家奠灵简，自昔仰神仙。","真子今将命，苍生福可传。","江山寻故国，城郭信依然。","二室遥相望，云回洞里天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d9cf7b72-41cc-4e86-a5ff-b3b142fc2f1f","tags":[]},{"id":"poem-d27e27b9b29aadac81aae63e","title":"眼儿媚·林下闺房世罕俦","author":"纳兰性德","dynasty":"清","verses":["林下闺房世罕俦，偕隐足风流。","今来忍见，鹤孤华表，人远罗浮。","中年定不禁哀乐，其奈忆曾游。","浣花微雨，采菱斜日，欲去还留。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-72","tags":[]},{"id":"poem-d2822840b9467b1b2e412a48","title":"竹马子・竹马儿·登孤垒荒凉","author":"柳永","dynasty":"宋","verses":["登孤垒荒凉，危亭旷望，静临烟渚。","对雌霓挂雨，雄风拂槛，微收烦暑。","渐觉一叶惊秋，残蝉噪晚，素商时序。","览景想前欢，指神京，非雾非烟深处。","向此成追感，新愁易积，故人难聚。","凭高尽日凝伫。","赢得消魂无语。","极目霁霭霏微，暝鸦零乱，萧索江城暮。","南楼画角，又送残阳去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-152","tags":["宋词三百首"]},{"id":"poem-d286d512564e6631393324be","title":"宿王昌龄隐居","author":"常建","dynasty":"唐","verses":["清溪深不测，隐处唯孤云。","松际露微月，清光犹为君。","茅亭宿花影，药院滋苔纹。","余亦谢时去，西山鸾鹤群。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c854a853-b015-4848-823b-a786659d33b3","tags":["唐诗三百首","隐逸","五言古诗","山水"]},{"id":"poem-d2909955838a42b11eec4bd6","title":"宿雨初晴春风顿至小园独步方多索寞之怀嘉句忽来骤引吟哦之兴仰攀高韵少达鄙诚","author":"李昉","dynasty":"宋","verses":["融融和气满亭台，寂绝无人访我来。","忽喜贰卿篇咏至，如闻三岛信音回。","偷闲旋要偿诗债，减俸惟将买树栽。","春旦两壶宣赐酒，一壶留著待君开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6870475a-44ad-48ea-a788-221897426da0","tags":[]},{"id":"poem-d2931e0b38dfd308a8a6027a","title":"春夜与诸公同宴呈陆郎中","author":"皎然","dynasty":"唐","verses":["南国宴佳宾，交情老倍亲。","月慙红泪烛，花笑白头人。","宝瑟絚余怨，琼枝不让春。","更闻歌子夜，桃李艳妆新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-35811b12-3828-42e8-8bc1-384b8cdfc57b","tags":[]},{"id":"poem-d2a339a3b71cabb777b13ae2","title":"枝巢","author":"释居简","dynasty":"宋","verses":["欲扫嚣尘迹，枚条自改门。","籁虚秋断续，花冷月黄昏。","鸠拙休相笑，鸿冥倘可扪。","逍遥与齐物，一等不须论。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-ace8cda5-6173-490d-a1d5-16370e247960","tags":[]},{"id":"poem-d2a7412e8e0ece76650a48dd","title":"晚楼闲坐","author":"王安石","dynasty":"宋","verses":["四顾山光接水光，凭栏十里芰荷香。","清风明月无人管，并作南来一味凉。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-晚樓閒坐","tags":[]},{"id":"poem-d2ae4cef28c4494eafc8e0e6","title":"古意九首 九","author":"贯休","dynasty":"唐","verses":["忆在山中时，丹桂花葳蕤。","红泉浸瑶草，白日生华滋。","箬屋开地𬬻，翠墙挂藤衣。","看经竹窗边，白猨三两枝。","东峰有老人，眼碧头骨奇。","种薤煮白石，旨趣如婴儿。","月上来打门，月落方始归。","授我微妙诀，恬澹无所为。","别来六七年，只恐白日飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-96cbc2fa-2200-466f-b851-2fb48769623d","tags":[]},{"id":"poem-d2c1ace2e3f52ca23768e1e8","title":"答鄜畤友人同宿见示","author":"马戴","dynasty":"唐","verses":["为客自堪悲，风尘日满衣。","承明无计入，旧隐但怀归。","雪积孤城暗，灯残晓角微。","相逢喜同宿，此地故人稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-30297498-3d72-4c4f-8bd2-9449f7f36bbb","tags":[]},{"id":"poem-d2c492fe8cbe43e1354232f7","title":"喜义兴权明府自君山至集陆处士羽青塘别业","author":"皎然","dynasty":"唐","verses":["应难久辞秩，暂寄君阳隐。","已见县名花，会逢闱是粉。","本自寻人至，宁因看竹引。","身关白云多，门占春山尽。","最赏无事心，篱边钓溪近。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3a48f3f5-6e61-4e22-8da8-0f164e72d54c","tags":[]},{"id":"poem-d2d1bf82765e51d5d2cf0fdf","title":"楼大参嘱珣起宗索孤山旧藁  其一","author":"释居简","dynasty":"宋","verses":["旧赋梅花欲反骚，效颦徒自不偿劳。","未寻处士孤山梦，误得先生一字褒。","剪剪衰兰甘草莽，朣朣华月在林皋。","从来平地神仙脚，咫尺钧衡步武高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-07ca37d0-bf78-401d-b558-2d3cfd344421","tags":[]},{"id":"poem-d2d212a832049db7056699ba","title":"哭陈陶","author":"张乔","dynasty":"唐","verses":["先生抱衰疾，不起茂陵间。","夕临诸孤少，荒居吊客还。","遗文禅东岳，留语葬乡山。","多雨铭旌故，残灯素帐闲。","乐章谁与集，陇树即堪攀。","神理今难问，予将呌帝关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5feeaa1c-7e0d-4bc7-809c-02a71ce5c376","tags":[]},{"id":"poem-d2d68ad666d7c8d8eb85886d","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(净)兀剌赤，兀剌赤。","门外等多时。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2905","tags":[]},{"id":"poem-d2eed52786b0962a4b2cfc10","title":"郊庙歌辞 明皇祀圜丘乐章 肃和","author":"不详","dynasty":"唐","verses":["止奏潜聆，登仪宿啭。","太玉躬奉，参钟首奠。","簠簋聿升，牺牲遰荐。","昭事颙若，存存以伣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-57fe80f8-d358-44eb-9b4f-7b9af4148431","tags":[]},{"id":"poem-d2fbe137e1ea6581fa22e41e","title":"清明日得家书四首  其一","author":"李纲","dynasty":"宋","verses":["去国三年久，离家万里余。","岂知戎马际，仍得棣华书。","金鼓震南国，松筠怀故庐。","寰区端若此，天意竟何如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-75d3cb16-cfbe-4172-977e-93936122eb7f","tags":[]},{"id":"poem-d2fdf9f9119a156e8159549a","title":"寄楚琼上人","author":"李咸用","dynasty":"唐","verses":["遥知无事日，静对五峰秋。","鸟隔寒烟语，泉和夕照流。","凭栏疎磬尽，瞑目远云收。","几句出人意，风高白雪浮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-53edfcf6-21b2-4677-9237-5dbfef58ab14","tags":[]},{"id":"poem-d2fe05473bd8da136b931c2b","title":"酬安之谢光兄弟见过","author":"司马光","dynasty":"宋","verses":["平时一二日，不见已相思。","况复闭关久，杳无携手期。","清谈胜妙药，高韵敌凉飔。","愧乏机云美，虚承青眼知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-964c287a-c2a4-4a5b-ae06-f4e0cb254d07","tags":[]},{"id":"poem-d301fce7858dae31843b997b","title":"韦侍郎山居","author":"王维","dynasty":"唐","verses":["幸忝君子顾，遂陪尘外踪。","闲花满岩谷，瀑水映杉松。","啼鸟忽临涧，归云时抱峰。","良游盛簪绂，继迹多夔龙。","讵枉青门道，胡闻长乐钟。","清晨去朝谒，车马何从容。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-65cea96b-411f-4bc8-85aa-9febbeaa4d2c","tags":[]},{"id":"poem-d302e212c969b925e4528f41","title":"赠姚合","author":"张籍","dynasty":"唐","verses":["丹凤城门向晓开，千官相次入朝来。","唯君独走冲尘土，下马桥边报直回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fa49873e-d6a9-4a2b-87f0-b9b3fb310b20","tags":[]},{"id":"poem-d303033511da7f8f701340ab","title":"监察十五叔东斋招李益端公会别","author":"孟郊","dynasty":"唐","verses":["欲知惜别情，泻水还清池。","此地有君子，芳兰步葳蕤。","手掇杂英珮，意摇春夜思。","莫作遶山云，循环无定期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a30db985-c13a-40e8-b1f6-da88559f78aa","tags":[]},{"id":"poem-d3072b16056c7c8235423932","title":"白华","author":"佚名","dynasty":"先秦","verses":["白华菅兮，白茅束兮。之子之远，俾我独兮。","英英白云，露彼菅茅。天步艰难，之子不犹。","滮池北流，浸彼稻田。啸歌伤怀，念彼硕人。","樵彼桑薪，卬烘于煁。维彼硕人，实劳我心。","鼓钟于宫，声闻于外。念子懆懆，视我迈迈。","有鹙在梁，有鹤在林。维彼硕人，实劳我心。","鸳鸯在梁，戢其左翼。之子无良，二三其德。","有扁斯石，履之卑兮。之子之远，俾我疧兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-228","tags":[]},{"id":"poem-d30cb27ce20c7f41e1075831","title":"夜携酒访崔正字","author":"刘得仁","dynasty":"唐","verses":["只应芸阁吏，知我僻兼愚。","吟兴忘饥冻，生涯任有无。","惨云埋远岫，阴吹吼寒株。","忽起围炉思，招携酒满壶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-136bbd8c-eb1c-43c1-8b24-782ca328e0c4","tags":[]},{"id":"poem-d312544a65c9cc8d96f7654a","title":"玉华仙子歌","author":"李康成","dynasty":"唐","verses":["紫阳仙子名玉华，珠盘承露饵丹砂。","转态凝情五云里，娇颜千岁芙蓉花。","紫阳彩女矜无数，遥见玉华皆掩嫭。","高堂初日不成妍，洛渚流风徒自怜。","璇阶霓绮阁，碧题霜罗幕。","仙娥桂树长自春，王母桃花未尝落。","上元夫人宾上清，深宫寂历厌层城。","解佩空怜郑交甫，吹箫不逐许飞琼。","溶溶紫庭步，渺渺瀛台路。","兰陵贵士谢相逢，济北风生尚回顾。","沧洲傲吏爱金丹，清心回望云之端。","羽盖霓裳一相识，传情写念长无极。","长无极，永相随。","攀霄历金阙，弄影下瑶池。","夕宿紫府云母帐，朝餐玄圃昆仑芝。","不学兰香中道绝，却教青鸟报相思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-76d53cae-3896-4d5a-a8ee-5594289c037a","tags":[]},{"id":"poem-d319dda915bdd16735990b44","title":"上行杯·草草离亭鞍马","author":"孙光宪","dynasty":"五代","verses":["草草离亭鞍马，从远道，此地分襟，燕宋秦吴千万里。","无辞一醉。野棠开，江草湿。伫立，沾泣，征骑骎骎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-36","tags":[]},{"id":"poem-d31ac9f9eb960ebe3e59f154","title":"元祐己巳岁维扬后斋为亳州使君蒋公写二首  其一","author":"米芾","dynasty":"宋","verses":["水竹风清一梦苏，涛生月破紫瓯须。","满堂爱客谈书画，且展宣王扇暍图。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-de963f10-a54b-443d-a669-b3892186c7c5","tags":[]},{"id":"poem-d31d967bac912c9eed99bb76","title":"云阳寺石竹花","author":"司空曙","dynasty":"唐","verses":["一自幽山别，相逢此寺中。","高低俱出叶，深浅不分丛。","野蝶难争白，庭榴暗让红。","谁怜芳最久，春露到秋风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-813ba0d9-9978-4a68-b5b1-9cd1e9ee82ff","tags":[]},{"id":"poem-d323c64f990ce24c20dd4f07","title":"人日立春","author":"卢仝","dynasty":"唐","verses":["春度春归无限春，今朝方始觉成人。","从今尅己应犹及，颜与梅花俱自新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-920bb4e9-69cb-4226-a45c-04ba744e19c3","tags":[]},{"id":"poem-d32538376c748d18add688b5","title":"天字谜","author":"韦添","dynasty":"唐","verses":["露头更一日，真是艳阳根。","（见《说郛》卷六一《清异录》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-97de461e-d911-4e82-9a6a-70c1f12e97a8","tags":[]},{"id":"poem-d33478bf3bd5faa4f30d6e9c","title":"大田","author":"佚名","dynasty":"先秦","verses":["大田多稼，既种既戒，既备乃事。以我覃耜，俶载南亩。","播厥百谷，既庭且硕，曾孙是若。","既方既皂，既坚既好，不稂不莠。去其螟螣，及其蟊贼，无害我田稚。田祖有神，秉畀炎火。","有渰萋萋，兴雨祈祈。雨我公田，遂及我私。彼有不获稚，此有不敛穧，彼有遗秉，此有滞穗，伊寡妇之利。","曾孙来止，以其妇子。馌彼南亩，田畯至喜。来方禋祀，以其骍黑，与其黍稷。以享以祀，以介景福。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-211","tags":[]},{"id":"poem-d33aec1e9b1a0a7c7a92e1f8","title":"奉和圣制同二相已下群臣乐游园宴","author":"崔尚","dynasty":"唐","verses":["春日照长安，皇恩宠庶官。","合钱承罢宴，赐帛复追欢。","供帐凭高列，城池入迥宽。","花催相国醉，鸟和乐人弹。","北阙云中见，南山树杪看。","乐游宜缔赏，舞咏惜将阑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-73fcfbdf-bb02-4490-a7bf-5ed9819a3ac2","tags":[]},{"id":"poem-d3465b9543bef23a7bc4575e","title":"过百牢关贻舟中者","author":"于邺","dynasty":"唐","verses":["蜀国少平地，方思京洛间。","远为千里客，来度百牢关。","帆影清江水，铃声碧草山。","不因名与利，尔我各应闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-59d82cdd-7383-472a-bf5d-936e788aa9ee","tags":[]},{"id":"poem-d3481073bccd4fb10d077ada","title":"诗上尧夫先生兼寄伯淳正叔  其一","author":"张载","dynasty":"宋","verses":["先生高卧洛城中，洛邑簪缨幸所同。","顾我成年清渭上，并游无侣又春风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1a0df2fe-cf00-4aec-b6cd-89e5b0911b32","tags":[]},{"id":"poem-d3495f73c1bbc818aa0d80a5","title":"春日杂兴  其二","author":"王同祖","dynasty":"宋","verses":["粉墙红杏半离披，春满人间花自知。","幽鸟不言如有思，等闲飞上海棠枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d286d3f2-0c8e-47ef-a2af-fe8d90c9bf5f","tags":[]},{"id":"poem-d3555bd63361534754c77aaf","title":"临江仙·本是白苹洲畔客","author":"苏庠","dynasty":"宋","verses":["本是白苹洲畔客，虎符卧镇江城。","归来犹得趁鸥盟。","柳丝摇晓市，杜若遍芳汀。","莫惜飞觞仍堕帻，柳边依约莺声。","水秋鲈熟正关情。","只愁宣室召，未许钓船轻。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-674","tags":[]},{"id":"poem-d355c553620636bd8decda3f","title":"山中期吉中孚","author":"李端","dynasty":"唐","verses":["行人路不同，花落到山中。","水暗蒹葭雾，月明杨柳风。","年华惊已掷，志业飒然空。","何必龙钟后，方期事远公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2f5fd8d9-88ef-4407-baa9-cb359cfb0668","tags":[]},{"id":"poem-d35e20c5266b19e69fe2cdc9","title":"句 一","author":"延寿","dynasty":"唐","verses":["言前体道乾坤窄，笔下搜吟海岳枯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ef14cfc5-2b28-474d-9282-a6f9e3e09981","tags":[]},{"id":"poem-d36ef1994a2d37093e96686e","title":"次韵梁广文重午吊古  其一","author":"陈造","dynasty":"宋","verses":["去年重午饮酒归，赓歌酬酢无俗子。","今年重午约同饮，更向诗人阅诗史。","平生玩物游戏尔，把酒孰知情所寄。","交朋径略形体中，嗜好本非杯勺里。","自昔骚人吟九辩，亦知令尹安三已。","宗英分严君恩重，一身摧折财稊米。","空遗楚俗千古哀，沈菰鼓鹢喧江涘。","属世休明偕五细，尚论取友吾谢此。","但制荷裳扈明月，无复凄风起苹芷。","明日菖盘荐急觞，容我客间先坐寐。","君来何止四者并，九室之春贱如水。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b88e3ce4-ac0d-4dae-a1e3-69056987025d","tags":[]},{"id":"poem-d37b3aafc8d956ee9640d466","title":"送礼部潘尚书致仕还建安","author":"徐铉","dynasty":"宋","verses":["名遂功成累复轻，鲈鱼因起旧乡情。","履声初下金华省，帆影看离石首城。","化剑津头寻故老，同亭会上问仙卿。","冥鸿高举真难事，相送何须泪满缨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0c29f3cb-9cbd-49fe-90df-74be8d7a9c36","tags":[]},{"id":"poem-d37b493d676bdd98ff2e35a5","title":"秋日","author":"耿𣲗","dynasty":"唐","verses":["返照入闾巷，忧来谁共语。","古道少人行，秋风动禾黍。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋日","tags":[]},{"id":"poem-d385c0d94aec1fb9a58614c4","title":"和陶渊明二十首  其一八","author":"陈造","dynasty":"宋","verses":["少从师友间，雅意效一得。","中年弹尘冠，欲起复回惑。","初无辅时具，吾责良易塞。","即今禹绍舜，群俊萃王国。","臣犹自知之，环省每愍默。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-93d21362-334f-4e58-b439-87ce0b78adc5","tags":[]},{"id":"poem-d388102458a4fb485cbbbfd8","title":"江城子·斜风细雨作春寒","author":"朱淑真","dynasty":"宋","verses":["斜风细雨作春寒。","对尊前。","忆前欢。","曾把梨花，寂寞泪阑干。","芳草断烟南浦路，和别泪，看青山。","昨宵结得梦夤缘。","水云间。","悄无言。","争奈醒来，愁恨又依然。","展转衾裯空懊恼，天易见，见伊难。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-864","tags":[]},{"id":"poem-d392820edc04e8bd932cd2b2","title":"小重山·碧水浮瓜纹簟前","author":"晁冲之","dynasty":"宋","verses":["碧水浮瓜纹簟前。","只知闲枕手，不成眠。","晚云如火雨晴天。","轻云远，亭外一声蝉。","池馆几年年。","倚阑催小艇，采新莲。","多情还到芰荷边。","应相忆，折藕看丝牵。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-673","tags":[]},{"id":"poem-d3937ac988de35ef20ea5ce2","title":"调笑・调笑令·翻翻绣袖上红茵","author":"邵伯温","dynasty":"宋","verses":["翻翻绣袖上红茵。","舞姬犹是旧精神。","坐中莫怪无欢意，我与将军是故人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-568","tags":[]},{"id":"poem-d3999e91fce422c219872855","title":"过洛阳城","author":"于邺","dynasty":"唐","verses":["古来利与名，俱在洛阳城。","九陌鼓初起，万车轮已行。","周秦时几变，伊洛水犹清。","二月中桥路，鸟啼春草生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-099c09a3-9bb4-46ac-b077-d3a47d03535d","tags":[]},{"id":"poem-d3a983cbca0d9bfb29eca904","title":"山中寄及第故人","author":"王建","dynasty":"唐","verses":["长长南山松，短短北磵杨。","俱承日月照，幸免斤斧伤。","去年与子别，诚言暂还乡。","如何弃我去，天路忽腾骧。","谁谓有双目，识貌不识肠。","岂知心内乖，著我薜萝裳。","寻君向前事，不叹今异翔。","往往空室中，寤寐说珪璋。","十年居此溪，松桂日苍苍。","自从无佳人，山中不辉光。","尽弃所留药，亦焚旧草堂。","还君誓已书，归我学仙方。","既为参与辰，各愿不相望。","始终名利途，慎勿罹咎殃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d8aa0031-9b68-4a19-b6d0-6695b1021c0b","tags":[]},{"id":"poem-d3b3eac8cb7425054cf74aec","title":"闺怨二首 二","author":"沈如筠","dynasty":"唐","verses":["陇底嗟长别，流襟一动君。","何言幽咽所，更作死生分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-eaa74fb2-a2e1-460e-86a0-e00d5b78066b","tags":[]},{"id":"poem-d3b7b42332fc67b032d8a795","title":"早行","author":"刘得仁","dynasty":"唐","verses":["万类半已动，此心宁自安。","月沈平野尽，星隐曙空残。","马渡横流广，人行湛露寒。","还思犹梦者，不信早行难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-190bb6b0-5c3e-46bd-afa7-1aa2f21e2fbf","tags":[]},{"id":"poem-d3bc213558c5c9f9fb85643e","title":"忆帝京·薄妆小靥闲情素","author":"黄庭坚","dynasty":"宋","verses":["薄妆小靥闲情素。","抱著琵琶凝伫。","慢拈复轻拢，切切如私语。","转拨割朱弦，一段惊沙去。","万里嫁、乌孙公主。","对易水、明妃不渡。","泪粉行行，红颜片片，指下花落狂风雨。","借问本师谁，敛拨当心住。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-700","tags":[]},{"id":"poem-d3bdd073a366b5d9df9e46cf","title":"恭谢庆成诗十韵","author":"苏颂","dynasty":"宋","verses":["圣孝当天世继明，两全能飨礼交行。","路朝躬款三年报，斋寝先端七日诚。","穹厚博临通肸蚃，祖宗严祀极专精。","冕章从质更新制，钟虡铿纯复旧声。","舞佾前陈徽烈茂，燎烟升达上仪成。","不祈厚福归诸己，务达厖恩及庶氓。","还御端闱孚大号，载颁元历庆鸿名。","欢谣沸渭盈都辇，协气旁流浃海瀛。","百辟旅庭纷岳抃，四方延首效葵倾。","帝心虔巩常无怠，亿万斯年享治平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-59432988-99cc-459d-a909-5fa80a8179a0","tags":[]},{"id":"poem-d3c1bfd948f070b2bee956cf","title":"见报以言者论六事其五皆靖康往故其一谓资囊士人上书以兾复用谪居海南震惧之余斐然有作  其二","author":"李纲","dynasty":"宋","verses":["非才自丏罢钧衡，百念灰寒岂复萌。","刚道资嚢上书者，不知谁继颍川生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-58e5287b-f637-42c5-ab8b-66c4cd94e6b2","tags":[]},{"id":"poem-d3c5912fb3759e933a39ffcc","title":"德山老人送茶至","author":"吕从庆","dynasty":"唐","verses":["数株香苕产松坡，野老新分半两多。","钓罢归来儿说与，引瓢旋汲涧中波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-00cf58db-89e0-477e-b7c3-be9752977f5b","tags":[]},{"id":"poem-d3ca6f27c5822cea3d7daf3e","title":"登山","author":"李涉","dynasty":"唐","verses":["终日昏昏醉梦间，忽闻春尽强登山。","因过竹院逢僧话，又得浮生半日闲。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-登山","tags":[]},{"id":"poem-d3d39a19455076e751b1b692","title":"赠山人二首  其一","author":"赵文","dynasty":"宋","verses":["水秀山明几百年，一朝城市化荒烟。","朱门富贵已如此，犹有人争旧墓田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-eba7db73-4cb3-4f78-ba95-953d258f51ed","tags":[]},{"id":"poem-d3d3a4fd8f425d8c72c36e42","title":"满庭芳","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["飞絮沾衣，残花随马，轻寒轻暖芳辰。","江山风物，偏动别离人。","回首高堂渐远，叹当时恩爱轻分。","伤情处，数声杜宇，客泪满衣襟。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4969","tags":[]},{"id":"poem-d3ec13ec0e3764666633d021","title":"酒泉子·春雨打窗","author":"张泌","dynasty":"五代","verses":["春雨打窗，惊梦觉来天气晓。","画堂深，红焰小，背兰釭。","酒香喷鼻懒开缸，惆怅更无人共醉。","旧巢中，新燕子，语双双。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-41","tags":[]},{"id":"poem-d3f810598afd3464e0cab24b","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 五","author":"易静","dynasty":"唐","verses":["九星位，当位（辛本、川本作「住」）八宫方。","惟有中官寄在二，术人运式细消详，依此我军强。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-62b9c682-13e2-40df-a2fa-477a60e2bfc3","tags":[]},{"id":"poem-d3fa0d37b4ae32f94528d43d","title":"遣兴五首 四","author":"杜甫","dynasty":"唐","verses":["猛虎凭其威，往往遭急缚。","雷吼徒咆哮，枝撑已在脚。","忽看皮寝处，无复睛闪烁。","人有甚于斯，足以劝元恶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9f89a106-6ff8-4deb-a2e5-30d5fe0da0f1","tags":[]},{"id":"poem-d40cc69d5c41198ce79172f5","title":"题水墨萱草水仙  其一","author":"释居简","dynasty":"宋","verses":["草欲忘忧蔓更滋，望云长在蜀天西。","萧萧风木添新恨，誊录精神答噬脐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b168f891-ee5d-463b-b71d-96121be30f77","tags":[]},{"id":"poem-d40fcb49da892d81f5c36a37","title":"庐山石镜","author":"鲍溶","dynasty":"唐","verses":["东岩采薇人，岩际朝见月。","怪堕幽萝间，非时更澄彻。","绿萝就玉兔，再与高鸟歇。","清光照掌中，始悟石上发。","谁传阴阳火，铸此天地物。","深影藏半山，虚轮带凝雪。","早回谢公赏，今遇樵夫说。","白日乘彩霞，翩翩对容发。","我图辨鬼魅，信美留烟阙。","形神乍相逢，竟夕难取别。","如其终身照，可化黄金骨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2ef68ff3-e364-4e3c-b94c-ce03bf079f09","tags":["庐山"]},{"id":"poem-d4100a5f0fb8b89c011dab4e","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 六","author":"易静","dynasty":"唐","verses":["甲加丙，龙反首（京本、川本作「首反」）为先。","丙甲相临鸟跌穴，时中得此自然全，得胜凯歌旋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f0bb7f76-0a5f-4a3f-8929-fb1d9be04d9a","tags":[]},{"id":"poem-d4102be4130ee5236da12c59","title":"和高邮监税李光道承务  其二","author":"华镇","dynasty":"宋","verses":["兰玉才华夙有芳，㧑谦高韵慕循墙。","风流自与迂疏厚，澹泊应须气味长。","屡见清谈能破的，行看素业骤成章。","日生鞅掌虽无尽，投隙当来语大方。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7ae2653e-169c-48b9-a1a6-1f0d14fb3a64","tags":[]},{"id":"poem-d411d4cc1ddd68155718463c","title":"青玉案·杏花时候匆匆别","author":"吴泳","dynasty":"宋","verses":["杏花时候匆匆别。","又欲迫、黄花节。","过了三年经八月。","骊驹声里，青鸿头畔，几见刀头折。","诸生立尽门前雪。","半偈重翻为渠说。","且莫从头烹瓠叶。","已呼童稚，多藏酒秫，共醉陶彭泽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-582","tags":[]},{"id":"poem-d41387a77a54451421ce5e0b","title":"送南迁客","author":"张籍","dynasty":"唐","verses":["去去远迁客，瘴中衰病身。","青山无限路，白首不归人。","海国战骑象，蛮州市用银。","一家分几处，谁见日南春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-33fac8f1-e14d-4392-8357-a3f64ad78e09","tags":[]},{"id":"poem-d4186f005a511a368caff0c1","title":"走马引","author":"李贺","dynasty":"唐","verses":["我有辞乡劒，玉锋堪截云。","襄阳走马客，意气自生春。","朝嫌劒花净，暮嫌劒光冷。","能持劒向人，不解持照身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9b8850ed-6675-484b-90da-32b3125eff83","tags":[]},{"id":"poem-d41b71233b7c5e8db367fefa","title":"诉衷情·高歌宴罢月初盈","author":"魏承班","dynasty":"五代","verses":["高歌宴罢月初盈，诗情引恨情。","烟露冷，水流轻，思想梦难成。","罗帐袅香平，恨频生。","思君无计睡还醒，隔层城。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-4","tags":[]},{"id":"poem-d41f708be574a8bbad4d489b","title":"题大庾岭北驿","author":"宋之问","dynasty":"唐","verses":["阳月南飞雁，传闻至此回。","我行殊未已，何日复归来？江静潮初落，林昏瘴不开。","明朝望乡处，应见陇头梅。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-058db0d1-0656-4e8f-ac49-87622e16b19b","tags":["唐诗三百首","五言律诗","思乡","带有地名","地名"]},{"id":"poem-d4345289098e4615bde6db69","title":"校猎义成喜逢大雪率题九韵以示群官","author":"明皇帝","dynasty":"唐","verses":["弧矢威天下，旌旗游近县。","一面施鸟罗，三驱教人战。","暮云成积雪，晓色开行殿。","皓然原隰同，不觉林野变。","北风勇士马，东日华组练。","触地银麞出，连山缟鹿见。","月兔落高矰，星狼下急箭。","既欣盈尺兆，复忆磻谿便。","岁丰将遇贤，俱荷皇天眷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8a2266dd-ed4e-4168-8464-ec32d966daaa","tags":[]},{"id":"poem-d44653a7d9ea6ae427f4ec00","title":"朱砂石","author":"缪岛云","dynasty":"唐","verses":["寒岩万丈陟崔嵬，只恐朱砂势便颓。","采蘩客闻雷擘去，卧云僧见鸟衔来。","丹霞迥烁嵌空片，红日斜分突兀堆。","傥得神僊惠纤粟，便能轻举向瑶台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f66e71ab-1ac5-4b7a-bd8b-6aead6cc415e","tags":[]},{"id":"poem-d44710e8a97d1d306537cf15","title":"偈 六","author":"契此","dynasty":"唐","verses":["由贪沦堕世波中，拾却贪嗔礼大雄。","直截凡情无所得，圆明寂照汝心宗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6d044fd2-b910-4415-a253-1d8173ae0177","tags":[]},{"id":"poem-d448d7edd4c5ed7556d050a5","title":"一萼红·古城阴","author":"姜夔","dynasty":"宋","verses":["古城阴。","有官梅几许，红萼未宜簪。","池面冰胶，墙腰雪老，云意还又沈沈。","翠藤共、闲穿径竹，渐笑语、惊起卧沙禽。","野老林泉，故王台榭，呼唤登临。","南去北来何事，荡湘云楚水，目极伤心。","朱户黏鸡，金盘簇燕，空叹时序侵寻。","记曾共，西楼雅集，想垂杨、还袅万丝金。","待得归鞍到时，只怕春深。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-128","tags":["宋词三百首"]},{"id":"poem-d44beeb07e294a0a9dda7923","title":"更漏子·菊花残","author":"晏殊","dynasty":"宋","verses":["菊花残，梨叶堕。","可惜良辰虚过。","新酒熟，绮筵开。","不辞红玉杯。","蜀弦高，羌管脆。","慢飐舞娥香袂。","君莫笑，醉乡人。","熙熙长似春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-448","tags":[]},{"id":"poem-d452bf5d1d78e154d84ec989","title":"奉和圣制送张说上集贤学士赐宴","author":"李暠","dynasty":"唐","verses":["偃武尧风接，崇文汉道恢。","集贤更内殿，清选自中台。","佐命留侯业，词华博物才。","天厨千品降，御酒百壶催。","鹓鹭方成列，神仙喜暂陪。","复欣同拜首，叨此颂良哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6c5b6a30-130d-4f9a-9e85-c3e5bc9522be","tags":[]},{"id":"poem-d45cba9d0fb5bc2f39270e6e","title":"·","author":"李观象","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-93beb1ad-0604-4ba9-92e1-c4b7f8cc5aa6","tags":[]},{"id":"poem-d463b0e03d147ccb031bcfaf","title":"山居四卉 拒霜","author":"李纲","dynasty":"宋","verses":["道人多种木芙蓉，晓着清霜分外红。","万叶千花本何有，因空成色色成空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8ba37e52-64f9-47be-a669-890e4f68b2b8","tags":[]},{"id":"poem-d4674fe4e788c2984b878ac5","title":"陪卢中丞闲游山寺","author":"皎然","dynasty":"唐","verses":["野寺出人境，舍舟登远峰。","林开明见月，万壑静闻钟。","拥烛明山翠，交麾动水容。","如何股肱守，尘外得相逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6383bc37-f778-4a0e-ba86-453a1c847052","tags":[]},{"id":"poem-d46881d2fd33834050746887","title":"颂","author":"文益","dynasty":"唐","verses":["理极忘情谓，如何有喻齐？","到头霜夜月，任情（《林间录》作「运」）落前溪。","菓熟猿兼（《林间录》作「兼猿」）重，山长似路迷。","举头残照在，元是住居西。","（《卍续藏经》本《大法眼文益禅师语录》，又见《林间录》卷下。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b61268d6-57ab-46e3-9c11-dbd050655941","tags":[]},{"id":"poem-d46c4f1ad02b290998818334","title":"家兄有和再用韵  其二","author":"艾可翁","dynasty":"宋","verses":["故人在何处，清梦或逢之。","老树秋声早，深窗曙色迟。","湿萤粘露草，惊鸟徙风枝。","琴破才支卧，知无钟子期。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-458a8de3-cee7-4dda-9304-a2692bb56de5","tags":[]},{"id":"poem-d4763832fefec6a10fe18e8e","title":"隋宫","author":"李商隐","dynasty":"唐","verses":["紫泉宫殿锁烟霞，欲取芜城作帝家。","玉玺不缘归日角，锦帆应是到天涯。","于今腐草无萤火，终古垂杨有暮鸦。","地下若逢陈后主，岂宜重问后庭花。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-670009c2-a701-4140-aa31-b4973f76d632","tags":["唐诗三百首","隋・唐・五代","七言律诗","讽刺","咏史"]},{"id":"poem-d4820c633ec04bb96f0a0ed4","title":"回军行","author":"李益","dynasty":"唐","verses":["关城榆叶早疎黄，日暮沙云古战场。","表请回军掩尘骨，莫教士卒哭龙荒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a841cfca-0ac2-4271-9ff0-34f87e837bbe","tags":[]},{"id":"poem-d487648364137cdb9ef50419","title":"次林子长韵","author":"陈造","dynasty":"宋","verses":["孤亭屹山椒，山灵信多助。","比肯迂玉节，来作数刻住。","江明山动色，取重以公故。","未须坐谭客，子弟自翘楚。","云岚远明灭，阡陌随指顾。","何以验人情，楚歈杂吴舞。","我来空想像，梦去上烟雨。","尚及拂云饮，醉狂烦杜举。","新欢偿昔游，幸会乃如许。","古人重一饭，志士赋盛遇。","归时混游人，健倒各扶路。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cd838fe9-bd34-47d9-9e01-1f0f4fe38a35","tags":[]},{"id":"poem-d48cc2df68405ef7605132f7","title":"女冠子·霞帔云发","author":"温庭筠","dynasty":"唐","verses":["霞帔云发，钿镜仙容似雪。","画愁眉，遮语回轻扇，含羞下绣帷。","玉楼相望久，花洞恨来迟。","早晚乘鸾去，莫相遗。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-48","tags":[]},{"id":"poem-d497bed8963e0c6ecfb72ec9","title":"苏东坡挽诗五首  其二","author":"米芾","dynasty":"宋","verses":["淋漓十幅草兼真，玉立如山老健身。","梦里赤猿真月纪，兴前白凤似年辰。","将寻贺监船虚返，欲近要离烈可亲。","忍死来还天有意，免称圣代杀文人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-856b95fe-52fd-41fd-95fe-cb4927d5db61","tags":[]},{"id":"poem-d4a62217bb22f72f692d0ad4","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(小旦)看孩儿容貌希奇，与相公面庞无二。","收留在此犹如嫡子，长成时莫忘了窦公恩义。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8949","tags":[]},{"id":"poem-d4bb24c4afeb0753c4eed4c4","title":"鹊巢","author":"佚名","dynasty":"先秦","verses":["维鹊有巢，维鸠居之。之子于归，百两御之。","维鹊有巢，维鸠方之。之子于归，百两将之。","维鹊有巢，维鸠盈之。之子于归，百两成之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-11","tags":[]},{"id":"poem-d4c8df07a19ace0e0a39ff73","title":"减字木兰花·摇毫铸藻","author":"葛立方","dynasty":"宋","verses":["摇毫铸藻。","纵有微之应压倒。","万里鹏程。","南省今书淡墨名。","胪传丹陛。","月里桂花先著袂。","雁塔高题。","玉季巍科尚觉低。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-525","tags":[]},{"id":"poem-d4c91d047be4b1a304aeb090","title":"东兴铺二首  其一","author":"赵文","dynasty":"宋","verses":["老人无泪与君啼，梦里相逢路竟迷。","二十三年崇胜寺，对床今夜是江西。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1396905e-2e32-46e6-9057-ef4518f213b1","tags":[]},{"id":"poem-d4d594614fdee1cb2c6859e4","title":"拟寒山 三","author":"泰钦","dynasty":"唐","verses":["谁信天真佛，兴悲几万般。","蓼花开古岸，白鹭立沙滩。","露滴庭莎长，云收溪月寒。","头头垂示处，子细好生观（《注华严经题法界观门颂》卷上作「看」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1b51ca70-b83e-409a-a13c-4f7f25c95fb4","tags":[]},{"id":"poem-d4ea460521894b0873123f5f","title":"恭闻诏书襃悼陈少阳赠官与一子恩泽赐缗钱五十万感涕四首  其三","author":"李纲","dynasty":"宋","verses":["屡将骾议叩枫宸，不为承恩始爱君。","谁使崔宁论卢杞，恨无庆忌救朱云。","死生一吷心应了，忠义千年笔有芬。","一介草茅言世务，从今不复数刘蕡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-be8b128e-7232-4974-ba5a-f3206adaac0b","tags":[]},{"id":"poem-d4f1e167e8709bf84636a2bc","title":"荆山","author":"李咸用","dynasty":"唐","verses":["良工指君疑，真玉却非玉。","寄言怀宝人，不须伤手足。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-909092a6-5da8-4673-b9f7-19d714ae81b7","tags":[]},{"id":"poem-d4f5018568f51ddae207b5a3","title":"瑞鹤仙·湿云黏雁影","author":"陆叡","dynasty":"宋","verses":["湿云黏雁影。","望征路愁迷，离绪难整。","千金买光景。","但疏钟催晓，乱鸦啼暝。","花暗省。","许多情、相逢梦境。","便行云、都不归来，也合寄将音信。","孤迥。","盟鸾心在，跨鹤程高，后期无准。","情丝待翦。","翻惹得，旧时恨。","怕天教何处，参差双燕，还染残朱剩粉。","对菱花、与说相思，看谁瘦损。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-1","tags":["宋词三百首"]},{"id":"poem-d4fbb76a3fa906ed35dc3281","title":"杨柳枝·两两黄鹂色似金","author":"温庭筠","dynasty":"唐","verses":["两两黄鹂色似金，袅枝啼露动芳音。","春来幸自长如线，可惜牵缠荡子心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-34","tags":[]},{"id":"poem-d504f37b3f60d5881867d54e","title":"自蒲圻临湘趋岳阳道中作十首  其七","author":"李纲","dynasty":"宋","verses":["远谪三湘欲卜居，试从詹尹拂占书。","昂昂愿作云间鹤，泛泛宁为波底鱼。","咿喔突梯真得计，洁亷正直却成疏。","益坚节操行吾志，龟策从来自不如。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d9dfb8d9-12ea-4e3e-9ee1-28e1ffc4c0c9","tags":[]},{"id":"poem-d50ab024cfba2ba1659eb90c","title":"浣溪沙·门隔花深梦旧游","author":"吴文英","dynasty":"宋","verses":["门隔花深梦旧游。","夕阳无语燕归愁。","玉纤香动小帘钩。","落絮无声春堕泪，行云有影月含羞。","东风临夜冷于秋。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-192","tags":["宋词三百首"]},{"id":"poem-d50bd4e1f0309e3a613df581","title":"渔家傲引・渔家傲·八月紫莼浮绿水","author":"洪适","dynasty":"宋","verses":["八月紫莼浮绿水。","细鳞巨口鲈鱼美。","画舫问渔篙暂舣。","欣然喜。","金齑顷刻尝珍味。","涌雾驱云天似洗。","静看星斗迎蟾桂。","枕棹眠蓑清不睡。","无名利。","谁人分得逍遥意。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-662","tags":[]},{"id":"poem-d5116a9528032bf115eede70","title":"句","author":"傅温","dynasty":"唐","verses":["霜坠中天衣觉冷，月临虚牗纸偏明。","春风暗翦庭前树，夜雨偷穿石上苔。","曲水两行排鴈齿，斜桥一道蹈龙鳞。","山深野客如禅客，夜久松声似雨声。","花疑汉女啼妆泪，水似吴娃笑弄筝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-618d535c-598c-409a-a42d-55c3f23f3b50","tags":[]},{"id":"poem-d5229f9c9375787b796b4177","title":"和段相公夏登张仪楼","author":"杨汝士","dynasty":"唐","verses":["从公城上来，秋近绝纤埃。","楼古秦规在，江分蜀望开。","远山标宿雪，末席本寒灰。","陪赏今为忝，临欢敢诉杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-06ba6fc0-85d9-4e2f-9701-a69616b9c0cb","tags":[]},{"id":"poem-d523a8b1dd771721d2ee5322","title":"卜算子·塞草晚才青","author":"纳兰性德","dynasty":"清","verses":["塞草晚才青，日落箫笳动，戚戚凄凄入夜分，催度星前梦。","小语绿杨烟，怯踏银河冻，行尽关山到白狼，相见惟珍重。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-86","tags":[]},{"id":"poem-d531cf095f0c03ec67a7d6c9","title":"尾声","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["正不过沿村转庄，撞工耕地。","我若得妆旦色如鱼似水，背杖鼓有何羞！提行头怕甚的！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-328","tags":[]},{"id":"poem-d53feb431cd613a9a19ab93f","title":"留别王侍御维","author":"孟浩然","dynasty":"唐","verses":["寂寂竟何待，朝朝空自归。","欲寻芳草去，惜与故人违。","当路谁相假，知音世所稀。","秪应守索寞，还掩故园扉。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7f4cacb5-cde8-40de-9b14-e223879cc2f4","tags":["唐诗三百首","归隐","友情","离别","哀怨","五言律诗"]},{"id":"poem-d5415db6bc544995ad501ed3","title":"奉送严大夫再领容府二首 一","author":"曹唐","dynasty":"唐","verses":["海风卷树冻岚消，忧国宁辞岭外遥。","自顾勤劳甘百战，不将功业负三朝。","劒澄黑水曾芟虎，箭劈黄云惯射雕。","代北天南尽成事，肯将心许霍嫖姚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e0fca6bb-3db4-476d-a052-a47ead7b87ae","tags":[]},{"id":"poem-d541d9524414364c0f0102b5","title":"寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物","author":"李绅","dynasty":"唐","verses":["南山白额同驯扰，亦变仁心去杀机。","不竞牛甘令买患，免遭狐假妄凭威。","渡河岂适他邦害，据谷终无暴物非。","尔效驺虞护生草，岂徒柔伏在淮淝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0baf4974-11e6-4c7a-82d2-b58d174cf01e","tags":[]},{"id":"poem-d548fc4f8e4a80aaa423355b","title":"有杕之杜","author":"佚名","dynasty":"先秦","verses":["有杕之杜，生于道左。彼君子兮，噬肯适我？中心好之，曷饮食之？","有杕之杜，生于道周。彼君子兮，噬肯来游？中心好之，曷饮食之？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-122","tags":[]},{"id":"poem-d54d55ff8f71374e54ec8b98","title":"边上","author":"张佖","dynasty":"宋","verses":["戍楼吹角起征鸿，猎猎寒旌背晚风。","千里暮烟愁不尽，一川秋草恨无穷。","山河惨澹关城闭，人物萧条市井空。","只此旅魂招未得，更堪回首夕阳中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-76aebb2b-7679-4072-bdd4-6cd40121ade6","tags":[]},{"id":"poem-d551cbfb23cc762a3c0d98a8","title":"月下独酌四首 一","author":"李白","dynasty":"唐","verses":["花间一壶酒，独酌无相亲。","举杯邀明月，对影成三人。","月既不解饮，影徒随我身。","暂伴月将影，行乐须及春。","我歌月裴回，我舞影零乱。","醒时同交欢，醉后各分散。","永结无情游，相期邈云汉。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-83e70b6e-ff59-4a3b-8e81-249ab0cda0c3","tags":["唐诗三百首","孤独","五言古诗","景中情","抒情","中秋","初中古诗","月下","饮酒","九年级下册(课外)"]},{"id":"poem-d5540fff89c3c4182a681974","title":"酒泉子·枕转簟凉","author":"牛希济","dynasty":"五代","verses":["枕转簟凉，清晓远钟残梦。","月光斜、帘影动，旧炉香。","梦中说尽相思事，纤手匀双泪。","去年春，今日意，断离肠。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-40","tags":[]},{"id":"poem-d560d878d76ef1d2634e1090","title":"没蕃故人","author":"张籍","dynasty":"唐","verses":["前年伐月支，城上没全师。","蕃汉断消息，死生长别离。","无人收废帐，归马识残旗。","欲祭疑君在，天涯哭此时。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-5ccd5188-0e5d-450e-8ec5-d6e661fac4f7","tags":["唐诗三百首","怀人","五言律诗"]},{"id":"poem-d5625b4a8e5275edb1d32f3c","title":"高都护骢马行","author":"杜甫","dynasty":"唐","verses":["安西都护胡青骢，声价歘然来向东。","此马临阵久无敌，与人一心成大功。","功成惠养随所致，飘飘远自流沙至。","雄姿未受伏枥恩，猛气犹思战场利。","腕促蹄高如踣铁，交河几蹴曾冰裂。","五花散作云满身，万里方看汗流血。","长安壮儿不敢骑，走过掣电倾城知。","青丝络头为君老，何由却出横门道。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-06b100d5-9899-4ae0-9eb8-66983943969f","tags":[]},{"id":"poem-d57698499d909bfed69db796","title":"送陈嘏登第作尉归觐","author":"赵嘏","dynasty":"唐","verses":["千峰归去旧林塘，溪县门前即故乡。","曾把桂夸春里巷，重怜身称锦衣裳。","洲迷翠羽云遮槛，露湿红蕉月满廊。","就养举朝人共羡，清资让却校书郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bddcc5c2-70c6-4669-9a1e-abe08ba0489e","tags":[]},{"id":"poem-d5841393adbb8b1331774ef1","title":"行军九日思长安故园","author":"岑参","dynasty":"唐","verses":["强欲登高去，无人送酒来。","遥怜故园菊，应傍战场开。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-行軍九日思長安故園","tags":[]},{"id":"poem-d5888f17a96ee4d0d002a410","title":"满庭芳·风老莺雏","author":"周邦彦","dynasty":"宋","verses":["风老莺雏，雨肥梅子，午阴嘉树清圆。","地卑山近，衣润费垆烟。","人静乌鸢自乐，小桥外、新绿溅溅。","凭栏久，黄芦苦竹，拟泛九江船。","年年。","如社燕，飘流瀚海，来寄修椽。","且莫思身外，长近尊前。","憔悴江南倦客，不堪听、急管繁弦。","歌筵畔，先安簟枕，容我醉时眠。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-230","tags":["宋词三百首"]},{"id":"poem-d58ea54c0537c5cb4db2837e","title":"芳树","author":"纳兰性德","dynasty":"清","verses":["连理无分影，同心岂独芳。","傍檐巢翡翠，临水宿鸳鸯。","叶叶含春思，枝枝向画廊。","君情若比树，妾意复何伤。","陌上谁攀折，闺中思复侵。","眼凝清露重，眉敛翠烟深。","羌笛临风曲，悲笳出塞音。","纵垂千万缕，那系别离心。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-252","tags":[]},{"id":"poem-d59039bfdc20c84c7b0bd54b","title":"赋得北方有佳人","author":"徐贤妃","dynasty":"唐","verses":["由来称独立，本自号倾城。","柳叶眉间发，桃花脸上生。","腕摇金钏响，步转玉环鸣。","纤腰宜宝袜，红衫艳织成。","悬知一顾重，别觉舞腰轻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6d46b6ce-5c89-4a0b-b496-c1718293fa90","tags":["写人","先秦两汉诗"]},{"id":"poem-d5921db4e6f1423b9597c21f","title":"春晦送客","author":"雍裕之","dynasty":"唐","verses":["野酌乱无巡，送君兼送春。","明年春色至，莫作未归人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0fe7c75d-41bb-461c-984c-bbcbd4756045","tags":[]},{"id":"poem-d5a89ffe3ed908e1c7e9c0aa","title":"叶梦授送家园梅花且以绝句十五章见示次其韵  其五","author":"李纲","dynasty":"宋","verses":["傍雨移梅趁小寒，探春几度独凭栏。","不知冷淡缘何事，偏得幽人带笑看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-59db40a7-d075-4d7a-8dfc-5a254dbd2677","tags":[]},{"id":"poem-d5aa4e9331ad99efd941aed7","title":"鹧鸪天·别绪如丝梦不成","author":"纳兰性德","dynasty":"清","verses":["别绪如丝梦不成，那堪孤枕梦边城。","因听紫塞三更雨，却忆红楼半夜灯。","书郑重，恨分明，天将愁味酿多情。","起来呵手封题处，偏到鸳鸯两字冰。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-118","tags":[]},{"id":"poem-d5abdefa11c3547e13e06137","title":"点绛唇·推枕南窗","author":"吴文英","dynasty":"宋","verses":["推枕南窗，拣花寒入单纱浅。","雨帘不卷。","空碍调雏燕。","一握柔葱，香染榴巾汗。","音尘断。","画罗闲扇。","山色天涯远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-455","tags":[]},{"id":"poem-d5aef1c6c46d4bc7d495090d","title":"九日止诸少登高","author":"艾可翁","dynasty":"宋","verses":["尘埃漠漠一千里，风雨潇潇十四陵。","立得身高愁转甚，龙山从此不须登。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-cb4f9651-ae44-4a1e-a481-fbc67ff6eae7","tags":[]},{"id":"poem-d5b3f4fc107c76e3e0c1ae2f","title":"章华宫行","author":"鲍溶","dynasty":"唐","verses":["烟渚南鸿呼晓群，章华宫娥怨行云。","十二巫峰仰天禄，金车何处邀云宿。","小腰婑堕三千人，宫衣水碧颜青春。","岂无一人似神女，忍使黛蛾常不伸。","黛蛾不伸犹自可，春朝诸处门常鏁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a36fbb37-c2b8-4ebb-a2a0-101022b81766","tags":[]},{"id":"poem-d5cc48159c9517be3848d096","title":"城南杂咏二十首 船斋","author":"张栻","dynasty":"宋","verses":["窗低芦苇秋，便有江湖思。","久已倦垂纶，游鱼不须避。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f30ad12e-f11a-46ca-997f-8c3b8d08657e","tags":[]},{"id":"poem-d5d022bc095437977c950c2e","title":"答郡守赵师夔","author":"金梁之","dynasty":"宋","verses":["王侯门户懒开颜，斗酒千钱一笑间。","无雪可欺青桧老，有天难管白云闲。","丹霄作客曾骑鹤，紫府为家不买山。","京口相逢又相别，只琴孤剑几时还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2408a404-919b-4bb3-9c4d-ebfc33883bfa","tags":[]},{"id":"poem-d5d3363d345666fed2f128bb","title":"凤鸣寺十八应真乃日本国所制密印僧典于沈氏沈施于凤鸣","author":"释居简","dynasty":"宋","verses":["木素上金泥，云衣整稻畦。","曾充僧典质，未到佛阶梯。","领众三韩北，分身两淛西。","一龛老风雨，谁与振幽栖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1120838c-8152-45fb-ab2c-bcf26e81f746","tags":[]},{"id":"poem-d5d70e45437fa6fdf8fcc82d","title":"奉和幸新丰温泉宫应制","author":"武平一","dynasty":"唐","verses":["秦王登碣石，周后袭昆仑。","何必在遐远，方称万宇尊。","我皇顺时豫，星驾动轩辕。","雄戟交驰道，清笳度国门。","回舆长乐观，校猎上林园。","行漏移三象，连营总八屯。","旌摇鹦鹉谷，骑转凤皇原。","绝壁苍苔古，灵泉碧溜温。","参差开水殿，䆗窱敞岩轩。","丰邑模犹在，骊宫迹尚存。","烟松衔翠幄，雪径遶花源。","侍从推玄草，文章召虎贲。","深仁浃夷夏，洪造溢乾坤。","谬忝王枚列，多慙雨露恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9252a97b-dd59-42be-93a8-afc66b7edce1","tags":[]},{"id":"poem-d5d9a58e22fb306c5f4f6e4d","title":"天仙子·天咫尺","author":"纳兰性德","dynasty":"清","verses":["好在软绡红泪积，漏痕斜罥菱丝碧。","古钗封寄玉关秋，天咫尺，人南北，不信鸳鸯头不白。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-167","tags":[]},{"id":"poem-d5da8f652931afbba0623d5a","title":"偶作五首 四","author":"贯休","dynasty":"唐","verses":["君子食即食，何必在珍华。","小人食不食，纵食如泥沙。","清歌且莫唱，妙舞亦休夸。","尔非凤灸麒麟肉，焉能一挂于齿牙。","去来去来归去来，红泉正洒芙蓉霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cf83f240-214a-4762-8364-fc752ecd5798","tags":[]},{"id":"poem-d5db684fcb42e4540c25e5a9","title":"纱窗恨·双双蝶翅涂铅粉","author":"毛文锡","dynasty":"五代","verses":["双双蝶翅涂铅粉，咂花心。","绮窗绣户飞来稳，画堂阴。","二三月爱随飘絮，伴落花，来拂衣襟。","更剪轻罗片，傅黄金。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-16","tags":[]},{"id":"poem-d5e4ce7c61b4a2051d0c2979","title":"古塞下曲七首 七","author":"贯休","dynasty":"唐","verses":["万战千征地，苍茫古塞门。","阴兵为客祟，恶酒发刀痕。","风落昆仑石，河崩苜蓿根。","将军更移帐，日日近西蕃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-601d8e9a-142c-4dfa-a390-8f422ac68e79","tags":[]},{"id":"poem-d5f164676e094aaf6dbff15f","title":"西江月·人我众生寿者","author":"张伯端","dynasty":"宋","verses":["人我众生寿者，宁分彼此高低。","法身通照没吾伊。","念念体分同异。","见是何曾是是，闻非未必非非。","往来诸用不相知。","生死谁能碍你。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-988","tags":[]},{"id":"poem-d5f6d9c57868a21db2d01fae","title":"保安寺","author":"江景防","dynasty":"唐","verses":["扰扰尘埃白日忙，偶然来谒赞公房。","行登峻岭跻攀倦，坐俯清泉笑傲凉。","林静鸟声酧客语，风来花气逐人香。","此时已觉凡尘断，分得高僧兴味长。","（见《宋诗纪事补遗》卷二引《开化县志》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7a8fa92e-bd7e-44ea-9aa4-c83166650e95","tags":[]},{"id":"poem-d6000b209010dae9fc481d81","title":"三年冬大礼五首 二","author":"曹唐","dynasty":"唐","verses":["海日西飞度禁林，太清宫殿月沉沉。","不闻北斗倾尧酒，空觉南风入舜琴。","歌压钧天闲梦尽，诏归秋水道情深。","雪风更起古杉叶，时送步虚清磬音。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-efc07ef1-651f-4c45-9125-010ad5982816","tags":[]},{"id":"poem-d6143ed2b7204096df4006f3","title":"九叹·远逝","author":"刘向","dynasty":"汉","verses":["志隐隐而郁怫兮，愁独哀而冤结。","肠纷纭以缭转兮，涕渐渐其若屑。","情慨慨而长怀兮，信上皇而质正。","合五岳与八灵兮，讯九鬿与六神。","指列宿以白情兮，诉五帝以置辞。","北斗为我折中兮，太一为余听之。","云服阴阳之正道兮，御后土之中和。","佩苍龙之蚴虬兮，带隐虹之逶蛇。","曳彗星之皓旰兮，抚朱爵与鵔鸃。","游清灵之飒戾兮，服云衣之披披。","杖玉策与朱旗兮，垂明月之玄珠。","举霓旌之墆翳兮，建黄𫄸之总旄。","躬纯粹而罔愆兮，承皇考之妙仪。","惜往事之不合兮，横汨罗而下沥。","乘隆波而南渡兮，逐江湘之顺流。","赴阳侯之潢洋兮，下石濑而登洲。","陆魁堆以蔽视兮，云冥冥而暗前。","山峻高以无垠兮，遂曾闳而迫身。","雪雰雰而薄木兮，云霏霏而陨集。","阜隘狭而幽险兮，石㟥嵯以翳日。","悲故乡而发忿兮，去余邦之弥久。","背龙门而入河兮，登大坟而望夏首。","横舟航而济湘兮，耳聊啾而戃慌。","波淫淫而周流兮，鸿溶溢而滔荡。","路曼曼其无端兮，周容容而无识。","引日月以指极兮，少须臾而释思。","水波远以冥冥兮，眇不睹其东西。","顺风波以南北兮，雾宵晦以纷纷。","日杳杳以西颓兮，路长远而窘迫。","欲酌醴以娱忧兮，蹇骚骚而不释。","叹曰：飘风蓬龙埃坲々兮，草木摇落时槁悴兮，遭倾遇祸不可救兮，长吟永欷涕究究兮，舒情陈诗冀以自免兮，颓流下陨身日远兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-50","tags":[]},{"id":"poem-d61c5b697d7d09ad2cd14c0f","title":"赐诸州刺史以题座右","author":"明皇帝","dynasty":"唐","verses":["眷言思共理，鉴梦想维良。","猗欤此推择，声绩著周行。","贤能既俟进，黎献实伫康。","视人当如子，爱人亦如伤。","讲学试诵论，阡陌劝耕桑。","虚誉不可饰，清知不可忘。","求名迹易见，安贞德自彰。","讼狱必以情，教民贵有常。","恤惸且存老，抚弱复绥强。","勉哉各祗命，知予眷万方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-66f00c11-e79e-4fe8-9890-1679f17a2dae","tags":[]},{"id":"poem-d623a26bad88022c3d715ae7","title":"赠陈望尧","author":"李咸用","dynasty":"唐","verses":["若说精通事艺长，词人争及孝廉郎。","秋萤短焰难盈案，邻烛余光不满行。","鹄箭亲疎虽异的，桂花高下一般香。","明时公道还堪信，莫遣锥锋久在囊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c10a1168-f269-43a4-98a9-4a809cd207fc","tags":[]},{"id":"poem-d6255842933971b971ae38dc","title":"辞辇行","author":"鲍溶","dynasty":"唐","verses":["汉家代久淳风薄，帝重微行极荒乐。","青娥三千奉一人，班女不以色事君。","朝停玉辇诏同载，三十六宫皆眄睐。","不惊六马缓天仪，从容鸣环前致辞。","君恩如海深难竭，妾命如丝轻易绝。","愿陪阿[母]同小星，敢使太阳齐万物。","周末幽王不可宗，妾闻上圣遗休风。","五更三老待白日，八十一女居深宫。","愿将辇内有余席，回赐忠臣妾恩泽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-517b0595-b7cd-41dc-9ee7-b8b4a9a2f076","tags":[]},{"id":"poem-d628c0ddce85d48aefa23b42","title":"金焦叶","author":"刘唐卿《白兔记》","dynasty":"元","verses":["奈何？奈何？恨苍天把人耽误。","自恨时乖运苦，怎禁这般折挫？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8806","tags":[]},{"id":"poem-d62cd301a0684b589a4c60c5","title":"使青夷军入居庸三首 一","author":"高适","dynasty":"唐","verses":["匹马行将久，征途去转难。","不知边地别，秪讶客衣单。","谿冷泉声苦，山空木叶干。","莫言关塞极，云雪尚漫漫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7f1a7ed4-5873-4cf1-9b28-3a454c54215a","tags":[]},{"id":"poem-d62e86ed9b3c72fd9b402142","title":"送萧炼师入四明山","author":"孟郊","dynasty":"唐","verses":["闲于独鹤心，大于高松年。","迥出万物表，高栖四明巅。","千寻直裂峰，百尺倒泻泉。","绛雪为我饭，白云为我田。","静言不语俗，灵踪时步天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-189a38ce-6ebf-44f1-a12f-f8cbb8e5d34e","tags":[]},{"id":"poem-d62ef0860756689d4af47389","title":"送日本国聘贺使晁巨卿东归","author":"包佶","dynasty":"唐","verses":["上才生下国，东海是西邻。","九译蕃君使，千年圣主臣。","野情偏得礼，木性本含真。","锦帆乘风转，金装照地新。","孤城开蜃阁，晓日上朱轮。","早识来朝岁，涂山玉帛均。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6d7b4fc4-62ae-48e7-a486-a8ff73caaf7d","tags":[]},{"id":"poem-d630d14296f35fff6cc3df13","title":"迎春乐·薄纱衫子裙腰匝","author":"欧阳修","dynasty":"宋","verses":["薄纱衫子裙腰匝。","步轻轻、小罗靸。","人前爱把眼儿札。","香汗透、胭脂蜡。","良夜永、幽期欢则洽。","约重会、玉纤频插。","执手临归，犹且更待留时霎。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-827","tags":[]},{"id":"poem-d639dd371c39d99f42b0941f","title":"喜迁莺·清明节","author":"薛昭蕴","dynasty":"五代","verses":["清明节，雨晴天，得意正当年。","马骄泥软绵连干，香袖半笼鞭。","花色融，人竞赏，尽是绣鞍朱鞅。","日斜无计更留连，归路草和烟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-36","tags":[]},{"id":"poem-d6490d70b1a12aef2fa27454","title":"洛阳行","author":"张籍","dynasty":"唐","verses":["洛阳宫阙当中州，城上峨峨十二楼。","翠华西去几时返，枭巢乳鸟藏蛰燕。","御门空锁五十年，税彼农夫修玉殿。","六街朝暮鼓冬冬，禁兵持戟守空宫。","百官月月拜章表，驿使相续长安道。","上阳宫树黄复绿，野豺入苑食麋鹿。","陌上老翁双泪垂，共说武皇巡幸时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cd8604be-3ce1-4a4e-891b-c30857a16fa0","tags":[]},{"id":"poem-d64e369bb81f790d0b64fcca","title":"江南曲五首 五","author":"丁仙芝","dynasty":"唐","verses":["始下芙蓉楼，言发瑯琊岸。","急为打船开，恶许傍人见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6a3f1a5a-ec6d-4d68-bc7c-1076f0e0b6c2","tags":[]},{"id":"poem-d650bdb63bff8aae38efd768","title":"蝴蝶儿·蝴蝶儿","author":"张泌","dynasty":"五代","verses":["蝴蝶儿，晚春时，阿娇初着淡黄衣，倚窗学画伊。","还似花间见，双双对对飞。","无端和泪拭胭脂，惹教双翅垂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-3","tags":[]},{"id":"poem-d65165e7aa0d7fc83479b995","title":"醉桃源・阮郎归·冬衣初染远山青","author":"周邦彦","dynasty":"宋","verses":["冬衣初染远山青。","双丝云雁绫。","夜寒袖湿欲成冰。","都缘珠泪零。","情黯黯，闷腾腾。","身如秋后蝇。","若教随马逐郎行。","不辞多少程。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-417","tags":[]},{"id":"poem-d6566c5b848aec6ee89f4cd3","title":"山上寒夜呈进士许棠","author":"曹松","dynasty":"唐","verses":["山寒草堂暖，寂夜有良朋。","读易分高烛，煎茶取折冰。","庭垂河半角，窗露月微棱。","俱入论心地，争无俗者憎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-08dcdae3-ed35-4cc2-9d88-20c75ed9a219","tags":[]},{"id":"poem-d657d3a21f71c83f823543cf","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)当时苦，值乱军，离乡背井兄妹分。","做小服低，看看地过冬还过春。","挨十生九死，举目无亲。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3083","tags":[]},{"id":"poem-d66076d69665d97667b71937","title":"上元日二首 二","author":"文宗皇帝","dynasty":"唐","verses":["蓂生三五叶初齐，上元羽客出桃蹊。","不爱仙家登真诀，愿蒙四海福黔黎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-78b979f0-9d59-4905-ae9a-5ba2445d0cf8","tags":[]},{"id":"poem-d66337905bf5a298e52c6d75","title":"醉落魄・一斛珠·陶陶兀兀","author":"黄庭坚","dynasty":"宋","verses":["陶陶兀兀。","尊前是我华胥国。","争名争利休休莫。","雪月风花，不醉怎生得。","邯郸一枕谁忧乐。","新诗新事因闲适。","东山小妓携丝竹。","家里乐天，村里谢安石。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-708","tags":[]},{"id":"poem-d669594212f007190e55917e","title":"寄赤松舒道士二首 一","author":"贯休","dynasty":"唐","verses":["不见高人久，空令鄙恡多。","遥思青嶂下，无那白云何。","子爱寒山子，歌惟乐道歌。","会应陪太守，一日到烟萝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-aebf17e6-ad83-4325-84a7-68e85ed85208","tags":[]},{"id":"poem-d66ebba6b3a1ad839949a243","title":"又一首（用前韵）","author":"詹敦仁","dynasty":"唐","verses":["可恨名存实已除，兰台芸阁复谁居？","豕鱼未识应多愧，尤恐在人成蠹书。","（以上二诗见《永乐大典》卷一九七八二「一屋」。","「局」字〖十八函一百七十八册〗。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c62134b6-0324-4713-8978-c5fe4d834ae2","tags":[]},{"id":"poem-d6711dd191a930e690128253","title":"夜听许十损诵诗爱而有作","author":"杜甫","dynasty":"唐","verses":["许生五台宾，业白出石壁。","余亦师粲可，身犹缚禅寂。","何阶子方便，谬引为匹敌。","离索晚相逢，包蒙欣有击。","诵诗浑游衍，四座皆辟易。","应手看捶钩，清心听鸣镝。","精微穿溟涬，飞动摧霹雳。","陶谢不枝梧，风骚共推激。","紫燕自超诣，翠駮谁翦剔。","君意人莫知，人间夜寥阒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b45024f9-099b-4057-897c-f5a2e3016dd3","tags":[]},{"id":"poem-d674a00eac08b9610604b9be","title":"点绛唇·蕙怨兰愁","author":"向","dynasty":"宋","verses":["蕙怨兰愁，玉台羞对啼妆面。","懒匀香脸。","不放眉峰展。","幽恨谁知，锦字空传远。","何时见。","为郎肠断。","不似郎情浅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-207","tags":[]},{"id":"poem-d67ee2799c810dd07c0de99f","title":"花庵二首  其二","author":"司马光","dynasty":"宋","verses":["谁谓花庵陋，徒为见者嗤。","此中胜广厦，人自不能知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f3ee2d59-3c78-43a4-8247-f16ba9525a9b","tags":[]},{"id":"poem-d6800a0ebd0d83b572f57714","title":"十无诗寄桂府杨中丞 八","author":"赵嘏","dynasty":"唐","verses":["孔融襟抱称名儒，爱物怜才与世殊。","今日宾堦忘姓字，当时省记荐雄无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4ae3c442-0ede-47d5-b311-e230a0de0c5f","tags":[]},{"id":"poem-d6824b795abd642d5b163f2b","title":"闻人说海北事有感","author":"聂夷中","dynasty":"唐","verses":["故乡归路隔高雷，见说年来事可哀。","村落日中眠虎豹，田园雨后长蒿莱。","海隅久已无春色，地底真成有劫灰。","荆棘满山行不得，不知当日是谁栽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d813c029-0b6d-4b89-b4ba-5d6d725e73d9","tags":[]},{"id":"poem-d68982e96e94c6f61b8b594d","title":"观书有感（其一）","author":"朱熹","dynasty":"宋","verses":["半亩方塘一鉴开，天光云影共徘徊。","问渠那得清如许，为有源头活水来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-觀書有感（其一）","tags":[]},{"id":"poem-d68b2427665f9f595949d8b1","title":"菩萨蛮·东风乌鹊西飞燕","author":"陈师道","dynasty":"宋","verses":["东风乌鹊西飞燕。","盈盈一水经年见。","急雨洗香车。","天回河汉斜。","离愁千载上。","相远长相望。","终不似人间。","回头万里山。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-292","tags":[]},{"id":"poem-d68c4ee01fc6a5ebde5188ef","title":"寄桂帅","author":"刘崇龟","dynasty":"唐","verses":["碧幢仁施合洪钧，桂树林前倍得春。","莫恋此时好风景，磻溪不是钓渔人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ebd38359-8583-4024-8d49-8c9d24b4e945","tags":[]},{"id":"poem-d68dcd99655961d4007ddaf5","title":"虞美人·宝檀金缕鸳鸯枕","author":"毛文锡","dynasty":"五代","verses":["宝檀金缕鸳鸯枕，绶带盘宫锦。","夕阳低映小窗明，南园绿树语莺莺，梦难成。","玉炉香暖频添炷，满地飘轻絮。","珠帘不卷度沉烟，庭前间立画秋千，艳阳天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-5","tags":[]},{"id":"poem-d694d7dfc70988019aa61db3","title":"兵要望江南 《周易》占候第二十六（三十七首） 二十七","author":"易静","dynasty":"唐","verses":["木官（辛本、川本作「宫」）旺，必定有雄兵。","金火不宜临世应，两家流血定交争，火鬼劫吾营（辛本、川本作「军」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a550ebc2-3d1b-4bfe-b308-bc24fb591959","tags":[]},{"id":"poem-d697a2288598303bdf5bdb16","title":"又泛西溪诗十首  其九","author":"刘跂","dynasty":"宋","verses":["淡淡春烟夕照微，渡头已觉行人稀。","玉罇未尽宾朋意，两桨何妨待月归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1b89f173-93ee-44d1-b9dc-d74c76c13eb4","tags":[]},{"id":"poem-d697be56acbd7fdd38788722","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末)听说事因，贤达院君常劝戒官人不听。","(小生)守清贫，且安分。","去谒高门求口食，路上哀告人。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1796","tags":[]},{"id":"poem-d69a10a6b5faf4cfe72ccc11","title":"好事近·马首望青山","author":"纳兰性德","dynasty":"清","verses":["马首望青山，零落繁华如此。","再向断烟衰草，认藓碑题字。","休寻折载话当年，只洒悲秋泪。","斜日十三陵下，过新丰猎骑。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-63","tags":[]},{"id":"poem-d6a1d94eeb18b92b676901fc","title":"西江月·席上芙蓉待暖","author":"毛滂","dynasty":"宋","verses":["席上芙蓉待暖，花间騕袅还嘶。","劝君不醉且无归。","归去因谁惜醉。","汤点瓶心未老，乳堆盏面初肥。","留连能得几多时。","两腋清风唤起。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-826","tags":[]},{"id":"poem-d6a5d586317a69e71ad4ebef","title":"送陈章甫","author":"李颀","dynasty":"唐","verses":["四月南风大麦黄，枣花未落桐阴长。","青山朝别暮还见，嘶马出门思旧乡。","陈侯立身何坦荡，虬须虎眉仍大颡。","腹中贮书一万卷，不肯低头在草莽。","东门酤酒饮我曹，心轻万事皆鸿毛。","醉卧不知白日暮，有时空望孤云高。","长河浪头连天黑，津口停舟渡不得。","郑国游人未及家，洛阳行子空叹息。","闻道故林相识多，罢官昨日今如何。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9e6cbc1b-95ed-406b-8c9d-d05876a1342c","tags":["唐诗三百首","送别","七言古诗"]},{"id":"poem-d6b138d4ea2f819bcc371ddb","title":"游春","author":"邢巨","dynasty":"唐","verses":["海岳三峰古，春皇二月寒。","绿潭渔子钓，红树美人攀。","弱蔓环沙屿，飞花点石关。","谿山游未厌，琴酌弄晴湾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-88512e94-1be0-4b4f-b65c-8f5890afd0b8","tags":[]},{"id":"poem-d6b20e188e86464ac4dbf7ab","title":"游长宁公主流杯池二十五首 二十四","author":"上官昭容","dynasty":"唐","verses":["参差碧岫耸莲花，潺湲绿水莹金沙。","何须远访三山路，人今已到九仙家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-991314e4-fee9-4758-9d63-917d9283f3f8","tags":[]},{"id":"poem-d6b6f0c80050a31730d66199","title":"哭林杰","author":"郑立之","dynasty":"唐","verses":["才高未及贾生年，何事孤魂逐逝川。","萤聚帐中人已去，鹤离台上月空圆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2ae0c1a8-700c-4f7d-a8a3-d6b3615f3dd7","tags":[]},{"id":"poem-d6c049287250bdc8264ea6ac","title":"清平乐·莺啼残月","author":"韦庄","dynasty":"五代","verses":["莺啼残月，绣阁香灯灭。","门外马嘶郎欲别，正是落花时节。","妆成不画蛾眉，含愁独倚金扉。","云路香尘莫扫，扫即郎去归迟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-48","tags":[]},{"id":"poem-d6c187642b32241979937af0","title":"偶得双鲤付厨作鲙以荐一觞","author":"李纲","dynasty":"宋","verses":["双鲤从来丙穴东，霜刀缕切脍花红。","银丝藿叶自争巧，玉筋金盘未觉空。","德饱姜侯情已重，诗成杜老志应同。","秋风笠泽鲈尤美，何日扁舟入手中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3a47f94c-ba99-4327-8897-ad287c258518","tags":[]},{"id":"poem-d6c65411991548c78d65c495","title":"道中景物甚胜吟赏不暇因复作此","author":"张栻","dynasty":"宋","verses":["支筇石壁听溪声，却看云山万叠新。","总是诗情吟不彻，一时分付与吾人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-dfdc6f72-568d-43e5-8cd3-2703c349473b","tags":[]},{"id":"poem-d6ce763d7f885cdd7773933f","title":"御筵送邓王","author":"徐铉","dynasty":"宋","verses":["禁里秋光似水清，林烟池影共离情。","暂移黄阁只三载，却望紫垣都数程。","满座清风天子送，随车甘雨郡人迎。","绮霞阁上诗题在，从此还应有颂声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3c050942-e64c-4e31-b5c0-45ae1acb79ca","tags":[]},{"id":"poem-d6cea6300780df94e5463e86","title":"柳初新·楚天来驾春相送","author":"沈蔚","dynasty":"宋","verses":["楚天来驾春相送。","半醉侧、花冠重。","瑶台清宴，群仙戏手，剪出彩衣犹动。","谁拂瑶琴巧弄。","舞丹山、三千雏凤。","艳冶轻盈放纵。","倚东风、从来遍宠。","桃花溪上，相思未断，愁掩五云真洞。","算曾揖、飞鸾双控。","等闲入、襄王春梦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-994","tags":[]},{"id":"poem-d6cf2ba76bd7700cf9b8c146","title":"挽潜斋王枢相  其二","author":"王柏","dynasty":"宋","verses":["治命深衣歛，亲题石像镌。","精神传巨扁，风月掩遗编。","流落人间境，陶镕物外天。","建安名教在，它日配先贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b45fede6-af76-49f6-b0c7-428411c3f123","tags":[]},{"id":"poem-d6d24d609f55041ac60202df","title":"偈十六首  其一○","author":"释士珪","dynasty":"宋","verses":["天晴开水路，无事设曹司。","病多谙药性，小慈妨大慈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3cf42b0e-094c-4a7b-b4be-3fd48f426b84","tags":[]},{"id":"poem-d6dec4eabd9d951150de51f5","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["劝你休窨约，随去你福至。","(合)最好俱丰足，衣共食随汝意。","(净)从小我惜伊，伊去婆亦去。","(合)病尤未可。","(净)婆一路当直你。","(合)厮系绾免忧虑，成伴侣几风味。","(净)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2708","tags":[]},{"id":"poem-d6e4667a750381ab92af26d8","title":"夏日","author":"戴敏","dynasty":"宋","verses":["乳鸭池塘水浅深，熟梅天气半晴阴。","东园载酒西园醉，摘尽枇杷一树金。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-夏日","tags":[]},{"id":"poem-d6eb7be54acf3b66cf22b335","title":"摊破浣溪沙·葬名花","author":"纳兰性德","dynasty":"清","verses":["林下荒苔道韫家，生怜玉骨委尘沙。","愁向风前无处说，数归鸦。","半世浮萍随逝水，一宵冷雨葬名花。","魂是柳绵吹欲碎，绕天涯。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-17","tags":[]},{"id":"poem-d6f4ba42a4500e2b7f5218ff","title":"忆多娇","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(外)你休怨忆，莫叹息，将他做小儿一般见识，巧语花言都勾讫。","凛凛雄威，凛凛雄威，管取前程显赫。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8833","tags":[]},{"id":"poem-d707d72724c7c95d60a7d8dc","title":"八哀诗 赠太子师汝阳郡王琎","author":"杜甫","dynasty":"唐","verses":["汝阳让帝子，眉宇真天人。","虬须似太宗，色映塞外春。","往者开元中，主恩视遇频。","出入独非时，礼异见群臣。","爱其谨洁极，倍此骨肉亲。","从容听朝后，或在风雪晨。","忽思格猛兽，苑囿腾清尘。","羽旗动若一，万马肃𬳽𬳽。","诏王来射雁，拜命已挺身。","箭出飞鞚内，上又回翠麟。","飜然紫塞翮，下拂明月轮。","胡人虽获多，天笑不为新。","王每中一物，手自与金银。","袖中谏猎书，扣马久上陈。","竟无衔橛虞，圣聪矧多仁。","官免供给费，水有在藻鳞。","匪唯帝老大，皆是王忠勤。","晚年务置醴，门引申白宾。","道大容无能，永怀侍芳茵。","好学尚贞烈，义形必沾巾。","挥翰绮绣扬，篇什若有神。","川广不可溯，墓久狐兔邻。","宛彼汉中郡，文雅见天伦。","何以开我悲，泛舟俱远津。","温温昔风味，少壮已书绅。","旧游易磨灭，衰谢增酸辛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-45110b81-0f02-4c85-b72a-f2210d10c12f","tags":[]},{"id":"poem-d71403a444513f295fc64983","title":"水调歌头·律吕自相召","author":"李纲","dynasty":"宋","verses":["律吕自相召，韶頀不难谐。","致君泽物，古来何世不须才。","幸可山林高卧，袖手何妨闲处，醇酒醉朋侪。","千里故人驾，不怕物情猜。","秋夜永，更秉烛，且衔杯。","五年离索，谁谓谈笑豁幽怀。","况我早衰多病，屏迹云山深处，俗客不曾来。","此日扫花径，蓬户为君开。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-553","tags":[]},{"id":"poem-d71557234830e42e48a9a05c","title":"卫公堂二首  其一","author":"曾协","dynasty":"宋","verses":["卫公精爽故依然，陈迹凄凉不记年。","亭远谩传曾起草，楼高无复见筹边。","新铭初勒风烟上，旧观都忘岁月迁。","从此南徐矜胜概，美谈留与后生传。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5a326f7c-b3fa-449c-ae4d-02ccb5cda07c","tags":[]},{"id":"poem-d721660bc2d5bfcfcba06e95","title":"樊川寒食二首 一","author":"卢延让","dynasty":"唐","verses":["寒食权豪尽出行，一川如画雨初晴。","谁家络络游春盛，担入花间轧轧声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-79c5dff5-e887-460a-a766-002473728f95","tags":[]},{"id":"poem-d727c910e14fe130d34083e5","title":"送郄先辈归觐华阴","author":"李洞","dynasty":"唐","verses":["桂枝博得凤栖枝，欢觐家僮舞翠微。","僧向瀑泉声里贺，鸟穿仙掌指间飞。","休停砚笔吟荒庙，永别灯笼赴锁闱。","骚雅近来颓丧甚，送君傍觉有光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e6ae71b0-28e1-4c6e-9c94-f5eec4b3e3c2","tags":[]},{"id":"poem-d727e464595fe2d03010744a","title":"玩仙灯","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生上)兀坐书斋，闻道有客来相访。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8317","tags":[]},{"id":"poem-d72e09aa1777d174aa3bdc21","title":"题汝坟驿壁三首  其二","author":"廖正一","dynasty":"宋","verses":["阿梅笄岁得同欢，懊恼情深解梦兰。","鶑语轻清花里话，柳条柔嫩掌中看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-727339fa-4639-4820-81b3-860b234a6ca4","tags":[]},{"id":"poem-d7363c22d6f643cf0812d60c","title":"聚秀阁","author":"王十朋","dynasty":"宋","verses":["清源山远水流长，九日溪山更异常。","高阁摩云聚秀气，禅僧秀气聚中藏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-8f867787-996e-4cba-8ff4-ef8da47aa9dd","tags":[]},{"id":"poem-d73931375bb390fe856cdac9","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四","author":"易静","dynasty":"唐","verses":["占主客，胜负蚤须知。","甲乙丙丁幷戊子（辛本、川本作「己」、京本作「字」），阳时出战主凶危，此事决（京本作「定」）无疑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-de86e2da-d617-4388-991b-64b40579a109","tags":[]},{"id":"poem-d740c2d38725429e8b73e773","title":"月夜","author":"王镃","dynasty":"宋","verses":["不眠行绕石池吟，月色如银夜正深。","山路无风枯叶静，时闻露滴响空林。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-45b20fdb-cece-4743-8292-e1882422140d","tags":[]},{"id":"poem-d740d5ea6656c310c71b0254","title":"浣溪沙·灯尽垂花月似霜","author":"欧阳修","dynasty":"宋","verses":["灯尽垂花月似霜。","薄帘映月两交光。","酒醺红粉自生香。","双手舞馀拖翠袖，一声歌已釂金觞。","休回娇眼断人肠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-745","tags":[]},{"id":"poem-d744c6b9e53066acc55db5f2","title":"送丁郎中守江州","author":"苏颂","dynasty":"宋","verses":["南朝兵马临江镇，圣世麾符守土臣。","此日风声动湓浦，早年名誉浃淮邻。","琵琶昔有天涯曲，𦩷𦪇今无境外人。","退食优游多胜赏，杯觞不负庾楼春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4b15b7e9-11c3-4395-a07c-2790c591ce20","tags":[]},{"id":"poem-d756bbf176472e48bffb9259","title":"过钱员外","author":"司空曙","dynasty":"唐","verses":["为郎头已白，迹向市朝稀。","移病居荒宅，安贫著败衣。","野园随客醉，雪寺伴僧归。","自说东峰下，松萝满故扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2c1a6bd0-a7fc-4485-97ce-040b34633957","tags":[]},{"id":"poem-d7599378ef20c970523cead1","title":"战城南","author":"徐九臯","dynasty":"唐","verses":["塞北狂胡旅，城南敌汉围。","巉岩一鼓气，拔利五兵威。","虏骑瞻山哭，王师拓地飞。","不应须宠战，当遂勒金徽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2f37ab92-d8ed-43f3-ba85-eff243e94cc9","tags":[]},{"id":"poem-d75c4cb489fe44d11321f56e","title":"一络索·过尽遥山如画","author":"纳兰性德","dynasty":"清","verses":["过尽遥山如画。","短衣匹马。","萧萧落木不胜秋，莫回首、斜阳下。","别是柔肠萦挂。","待归才罢。","却愁拥髻向灯前，说不尽、离人话。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-160","tags":[]},{"id":"poem-d75ca85edbf11103a4cbe1c3","title":"永明山居诗（六十九首） 十九","author":"延寿","dynasty":"唐","verses":["青山一坐万缘休，努力应须与古俦。","散诞襟怀因绝趣，消疎活计为无求。","花明小砌和春月，松暗前轩带雨秋。","景像自开还自合，怡然何必更忘忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fa78ef0f-5331-41d1-8560-74de9b68dfc7","tags":[]},{"id":"poem-d75e2a3e3d58b0f70dc72e30","title":"长安道","author":"贯休","dynasty":"唐","verses":["憧憧合合，八表一辙。","黄尘雾合，车马火热。","名汤风雨，利辗霜雪。","千车万驮，半宿关月。","上有尧禹，下有夔卨。","紫气银轮兮，常覆金阙。","仙掌捧日兮，浊河澄澈。","愚将草木兮有言，与华封人兮不别。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fb0c3d10-e664-45ff-b654-6be68cae002c","tags":[]},{"id":"poem-d75f7be3644c853284863aed","title":"送魏万之京","author":"李颀","dynasty":"唐","verses":["朝闻游子唱离歌，昨夜微霜初渡河。","鸿鴈不堪愁里听，云山况是客中过。","关城树色催寒近，御苑砧声向晚多。","莫见长安行乐处，空令岁月易蹉跎。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6340ef19-35e2-4194-96a9-3ee0a667905b","tags":["唐诗三百首","叙事","七言律诗","写景","友情","抒情","送别"]},{"id":"poem-d766190136645bcd03848d96","title":"夜半乐·冻云黯淡天气","author":"柳永","dynasty":"宋","verses":["冻云黯淡天气，扁舟一叶，乘兴离江渚。","渡万壑千岩，越溪深处。","怒涛渐息，樵风乍起，更闻商旅相呼。","片帆高举。","泛画鹢、翩翩过南浦。","望中酒旆闪闪，一簇烟村，数行霜树。","残日下，渔人鸣榔归去。","败荷零落，衰杨掩映，岸边两两三三，浣沙游女。","避行客、含羞笑相语。","到此因念，绣阁轻抛，浪萍难驻。","叹后约丁宁竟何据。","惨离怀，空恨岁晚归期阻。","凝泪眼、杳杳神京路。","断鸿声远长天暮。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-149","tags":["宋词三百首"]},{"id":"poem-d7685a22fd860ca81d231b7e","title":"谒金门·空相忆","author":"韦庄","dynasty":"五代","verses":["空相忆，无计得传消息。","天上嫦娥人不识，寄书何处觅。","新睡觉来无力，不忍把伊书迹。","满院落花春寂寂，断肠芳草碧。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-1","tags":[]},{"id":"poem-d7688c4349592370b9e64d0b","title":"偈颂（幷序○序为南岳齐己撰） 九十四","author":"居遁","dynasty":"唐","verses":["天真元具足，修证转差回。","弃本却逐末，祇守一场呆。","（以上九十五首，均见《卍续藏经》本宋释子升、如祐编《禅门诸祖师偈颂》卷上之上。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-16d8217d-d932-4259-8f6e-0be5a12a273e","tags":["衡山"]},{"id":"poem-d76a25b87c48650287e0afb4","title":"送丘二十二之苏州","author":"崔峒","dynasty":"唐","verses":["积水与寒烟，嘉禾路几千。","孤猨啼海岛，群雁起湖田。","曾见长洲苑，尝闻大雅篇。","却将封事去，知尔爱闲眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-db8be32b-7191-4e61-a10f-1d3a20f533e9","tags":[]},{"id":"poem-d771fcf08153bd134c7ea5cf","title":"和钱侍郎甘露","author":"孟郊","dynasty":"唐","verses":["玄天何以言，瑞露青松繁。","忽见垂书迹，还惊涌澧源。","春枝晨袅袅，香味晓翻翻。","子礼忽来献，臣心固易敦。","清风惜不动，薄雾肯蒙昏。","嘉昼色更晶，仁慈久乃存。","一方难独占，天下恐争论。","侧听飞中使，重荣华德门。","从公乐万寿，余庆及儿孙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2563d416-de47-440e-a4ae-30ffaa438e29","tags":[]},{"id":"poem-d77717489639227609a090c3","title":"鹊桥仙·届征途","author":"柳永","dynasty":"宋","verses":["届征途，携书剑，迢迢匹马东去。","惨离怀，嗟少年易分难聚。","佳人方恁缱绻，便忍分鸳侣。","当媚景，算密意幽欢，尽成轻负。","此际寸肠万绪。","惨愁颜、断魂无语。","和泪眼、片时几番回顾。","伤心脉脉谁诉。","但黯然凝伫。","暮烟寒雨。","望秦楼何处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-118","tags":[]},{"id":"poem-d7874bfc3f6bfc53cb23e410","title":"冬日金陵制幕书事  其四","author":"王同祖","dynasty":"宋","verses":["薄晚官军得胜归，家家户户挂旌旗。","阵前纪律明于日，师入城来半不知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5f0c530f-755a-49c8-9e46-00d7aef4d881","tags":[]},{"id":"poem-d789f86a05fff245de311776","title":"踏莎行·二社良辰","author":"陈尧佐","dynasty":"宋","verses":["二社良辰，千家庭院。","翩翩又见新来燕。","凤凰巢稳许为邻，潇湘烟暝来何晚。","乱入红楼，低飞绿岸。","画梁时拂歌尘散。","为谁归去为谁来，主人恩重珠帘卷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-13","tags":[]},{"id":"poem-d793fed53a7b12bcf96bff0d","title":"猗嗟","author":"佚名","dynasty":"先秦","verses":["猗嗟昌兮，颀而长兮。抑若扬兮，美目扬兮。巧趋跄兮，射则臧兮。","猗嗟名兮，美目清兮。仪既成兮，终日射侯，不出正兮，展我甥兮。","猗嗟娈兮，清扬婉兮。舞则选兮，射则贯兮，四矢反兮，以御乱兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-105","tags":[]},{"id":"poem-d79ebd15da0e89f2d5951f49","title":"拟冬日景忠山应制·岧峣铁凤锁琳宫","author":"纳兰性德","dynasty":"清","verses":["岧峣铁凤锁琳宫，亲侍銮舆度碧空。","圣主岂因崇象教，宸游直自接鸿蒙。","远山雪有一峰白，别浦枫余几树红。","天意不教常肃杀，伫看宇宙遍春风。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-247","tags":[]},{"id":"poem-d79f3aed20f90648c2d25cc8","title":"同诸公寻李方直不遇","author":"包何","dynasty":"唐","verses":["闻说到扬州，吹箫忆旧游。","人来多不见，莫是上迷楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-13603ba0-f3e4-43a0-adb6-eb8f9dc839ca","tags":[]},{"id":"poem-d7a9945cfa6487755d365776","title":"浣溪沙·堤上游人逐画船","author":"欧阳修","dynasty":"宋","verses":["堤上游人逐画船。","拍堤春水四垂天。","绿杨楼外出秋千。","白发戴花君莫笑，六么催拍盏频传。","人生何处似尊前。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-739","tags":[]},{"id":"poem-d7aceb11ad9e9e7f6801296f","title":"和钱秘监旅居秋怀二首  其一","author":"徐铉","dynasty":"宋","verses":["秘监疏朝谒，门前长绿苔。","未愁玄鬓改，且喜素秋来。","独坐翻棋势，闲行绕药栽。","凉风入书幌，时动水沉灰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-370368f1-8e86-46a9-9d4f-dbc7fcb33a97","tags":[]},{"id":"poem-d7b2c1ad62a13665aadbce6a","title":"修史亭三首 三","author":"司空图","dynasty":"唐","verses":["乌纱巾上是青天，检束酬知四十年。","谁料平生臂鹰手，挑灯自送佛前钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9425c4a9-c282-4cca-bf59-6fe67d58ef98","tags":[]},{"id":"poem-d7c6c6fe28c8d337a6283fce","title":"天宝初南曹小司寇舅于我太夫人堂下累土为山一匮盈尺以代彼朽木承诸焚香瓷瓯瓯甚安矣旁植慈竹盖兹数峰嵚岑婵娟宛有尘外数致乃不知兴之所至而作是诗","author":"杜甫","dynasty":"唐","verses":["一匮功盈尺，三峰意出群。","望中疑在野，幽处欲生云。","慈竹春阴覆，香炉晓势分。","惟南将献寿，佳气日氛氲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2c4755aa-a07d-4e0a-97b6-afdf906a3f00","tags":[]}];
